CREATE OR REPLACE FUNCTION public._admin_backfill_saved_payment_methods(p_camp_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_me     jsonb;
    v_fams   jsonb := '{}'::jsonb;
    rec      record;
    v_fam    jsonb;
    v_pms    jsonb;
    v_token  text;
    v_label  text;
    v_last4  text;
    v_added  text;
    v_proc   text;
    v_changed boolean := false;
    v_added_n int := 0;
BEGIN
    SELECT value INTO v_me FROM camp_state_kv
     WHERE camp_id = p_camp_id AND key = 'campistryMe';
    IF v_me IS NULL OR jsonb_typeof(public.camp_families_object(p_camp_id)) <> 'object' THEN
        RETURN jsonb_build_object('success', true, 'added', 0, 'note', 'no families');
    END IF;

    FOR rec IN SELECT key, value FROM jsonb_each(public.camp_families_object(p_camp_id)) LOOP
        v_fam   := rec.value;
        v_token := NULLIF(btrim(COALESCE(v_fam->>'byopCustomerRef', '')), '');
        v_pms   := CASE WHEN jsonb_typeof(v_fam->'savedPaymentMethods') = 'array'
                        THEN v_fam->'savedPaymentMethods' ELSE '[]'::jsonb END;

        -- Only families with a legacy BYOP token whose token isn't already listed.
        IF v_token IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM jsonb_array_elements(v_pms) m WHERE m->>'token' = v_token
        ) THEN
            v_proc  := COALESCE(NULLIF(btrim(COALESCE(v_fam->>'byopProcessor', '')), ''), 'banquest');
            v_label := NULLIF(btrim(COALESCE(v_fam->>'paymentMethodLabel', '')), '');
            -- Recover the last 4 from whatever the label recorded ("•••• 4242",
            -- "Card ···· 4242"); blank if the label never carried digits.
            v_last4 := NULLIF(right(regexp_replace(COALESCE(v_label, ''), '[^0-9]', '', 'g'), 4), '');
            v_added := COALESCE(NULLIF(btrim(COALESCE(v_fam->>'cardSavedDate', '')), ''), now()::text);

            v_pms := v_pms || jsonb_build_object(
                'id',        'pm_' || replace(gen_random_uuid()::text, '-', ''),
                'type',      'card',
                'processor', v_proc,
                'token',     v_token,
                'last4',     COALESCE(v_last4, ''),
                'label',     COALESCE(v_label, CASE WHEN v_last4 IS NOT NULL
                                                    THEN 'Card ···· ' || v_last4
                                                    ELSE 'Card on file' END),
                'addedDate', v_added,
                'isDefault', (jsonb_array_length(v_pms) = 0)
            );
            v_fam := jsonb_set(v_fam, '{savedPaymentMethods}', v_pms, true);
            -- Cards exist now, so the flag Link reads must agree.
            v_fam := jsonb_set(v_fam, '{cardOnFile}', 'true'::jsonb, true);
            v_changed := true;
            v_added_n := v_added_n + 1;
        END IF;

        PERFORM public.camp_family_save(p_camp_id, rec.key, v_fam);
    END LOOP;

    IF v_changed THEN
    END IF;

    RETURN jsonb_build_object('success', true, 'added', v_added_n);
END;
$function$

CREATE OR REPLACE FUNCTION public._credit_canteen_balance_from_processor__by_name(p_camp_id uuid, p_camper_name text, p_amount numeric, p_processor_key text, p_external_transaction_id text, p_source text DEFAULT 'parent'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_locked_acct jsonb;
    v_value      jsonb;
    v_bal        numeric;
    v_already    boolean;
    v_roster_ok  boolean;
    v_is_auto    boolean := (p_source = 'autoreload');
    v_items      text;
    v_kind       text;
    now_ts       timestamptz := now();
BEGIN
    IF p_camp_id IS NULL OR p_camper_name IS NULL OR btrim(p_camper_name) = '' THEN
        RETURN jsonb_build_object('success', false, 'error', 'missing_params');
    END IF;
    IF p_amount IS NULL OR p_amount <= 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_amount');
    END IF;
    IF p_external_transaction_id IS NULL OR btrim(p_external_transaction_id) = '' THEN
        RETURN jsonb_build_object('success', false, 'error', 'missing_transaction_id');
    END IF;


    -- 219: one camper's row, not the camp's document.
    v_value := NULL::jsonb;  -- document no longer read
    v_locked_acct := public.canteen_account_lock(p_camp_id, p_camper_name);


    SELECT EXISTS (
        SELECT 1 FROM canteen_transactions t
         WHERE t.camp_id = p_camp_id AND t.payload->>'byopTransactionId' = p_external_transaction_id
    ) INTO v_already;
    IF v_already THEN
        RETURN jsonb_build_object(
            'success', true, 'alreadyProcessed', true,
            'balance', COALESCE((v_locked_acct->>'balance')::numeric, 0)
        );
    END IF;

    -- Defense-in-depth roster check (same as migration 132).
    SELECT (value->'app1'->'camperRoster' ? p_camper_name) INTO v_roster_ok
    FROM camp_state_kv WHERE camp_id = p_camp_id AND key = 'app1';
    v_roster_ok := COALESCE(v_roster_ok, false);

    v_bal := round(COALESCE((v_locked_acct->>'balance')::numeric, 0) + p_amount, 2);

    PERFORM public.canteen_account_save(p_camp_id, p_camper_name,
        COALESCE(v_locked_acct, '{"dailyLimit":10,"spentToday":0}'::jsonb)
            || jsonb_build_object('balance', v_bal));

    v_items := CASE WHEN v_is_auto THEN 'Auto-reload top-up' ELSE 'Funds added by parent (online)' END;
    v_kind  := CASE WHEN v_is_auto THEN 'autoreload' ELSE 'deposit' END;

    PERFORM public.canteen_post(p_camp_id, p_camper_name,
        jsonb_build_object(
            'time',   to_char(now_ts, 'HH12:MI AM'),
            'camper', p_camper_name,
            'items',  v_items,
            'amount', p_amount,
            'type',   'credit',
            'kind',   v_kind,
            'method', p_processor_key,
            'date',   to_char(now_ts, 'YYYY-MM-DD'),
            'byopTransactionId', p_external_transaction_id,
            'timestamp', (extract(epoch from now_ts) * 1000)::bigint
        ));


    RETURN jsonb_build_object('success', true, 'balance', v_bal, 'rosterVerified', v_roster_ok);
END;
$function$

CREATE OR REPLACE FUNCTION public._credit_canteen_balance_from_stripe__by_name(p_camp_id uuid, p_camper_name text, p_amount numeric, p_payment_intent_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_locked_acct jsonb;
    v_value      jsonb;
    v_bal        numeric;
    v_already    boolean;
    v_roster_ok  boolean;
    now_ts       timestamptz := now();
BEGIN
    IF p_camp_id IS NULL OR p_camper_name IS NULL OR btrim(p_camper_name) = '' THEN
        RETURN jsonb_build_object('success', false, 'error', 'missing_params');
    END IF;
    IF p_amount IS NULL OR p_amount <= 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_amount');
    END IF;
    IF p_payment_intent_id IS NULL OR btrim(p_payment_intent_id) = '' THEN
        RETURN jsonb_build_object('success', false, 'error', 'missing_payment_intent');
    END IF;


    -- 219: one camper's row, not the camp's document.
    v_value := NULL::jsonb;  -- document no longer read
    v_locked_acct := public.canteen_account_lock(p_camp_id, p_camper_name);


    -- Idempotency: has this exact PaymentIntent already been credited?
    SELECT EXISTS (
        SELECT 1 FROM canteen_transactions t
         WHERE t.camp_id = p_camp_id AND t.payload->>'stripePaymentIntentId' = p_payment_intent_id
    ) INTO v_already;
    IF v_already THEN
        RETURN jsonb_build_object(
            'success', true, 'alreadyProcessed', true,
            'balance', COALESCE((v_locked_acct->>'balance')::numeric, 0)
        );
    END IF;

    -- Defense-in-depth roster check -- the real gate is in stripe-checkout
    -- (campOwnsCamper, checked BEFORE the Checkout Session is even created).
    -- By the time this RPC runs, Stripe has already captured real money, so
    -- a missing roster match is logged (rosterVerified:false) for office
    -- follow-up rather than refused -- refusing here would strand captured
    -- money with nowhere to go.
    SELECT (value->'app1'->'camperRoster' ? p_camper_name) INTO v_roster_ok
    FROM camp_state_kv WHERE camp_id = p_camp_id AND key = 'app1';
    v_roster_ok := COALESCE(v_roster_ok, false);

    v_bal := round(COALESCE((v_locked_acct->>'balance')::numeric, 0) + p_amount, 2);

    PERFORM public.canteen_account_save(p_camp_id, p_camper_name,
        COALESCE(v_locked_acct, '{"dailyLimit":10,"spentToday":0}'::jsonb)
            || jsonb_build_object('balance', v_bal));

    PERFORM public.canteen_post(p_camp_id, p_camper_name,
        jsonb_build_object(
            'time',   to_char(now_ts, 'HH12:MI AM'),
            'camper', p_camper_name,
            'items',  'Funds added by parent (online)',
            'amount', p_amount,
            'type',   'credit',
            'kind',   'deposit',
            'method', 'stripe',
            'date',   to_char(now_ts, 'YYYY-MM-DD'),
            'stripePaymentIntentId', p_payment_intent_id,
            'timestamp', (extract(epoch from now_ts) * 1000)::bigint
        ));


    RETURN jsonb_build_object('success', true, 'balance', v_bal, 'rosterVerified', v_roster_ok);
END;
$function$

CREATE OR REPLACE FUNCTION public._enforce_processor_conformance()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_conf jsonb;
    v_miss text;
BEGIN
    v_conf := public.processor_conformance(NEW.processor_key);
    IF COALESCE((v_conf->>'ok')::boolean, false) THEN
        RETURN NEW;
    END IF;

    SELECT string_agg(m->>'capability', ', ')
      INTO v_miss
      FROM jsonb_array_elements(COALESCE(v_conf->'missing', '[]'::jsonb)) m;

    RAISE EXCEPTION
        'Cannot connect a camp to payment processor "%" — it does not declare: %. '
        'Every processor must be able to charge, refund, store and re-charge a '
        'card token, and report a dispute. A processor that cannot report a '
        'dispute lets money leave the camp''s bank account with nothing in '
        'Campistry to show for it. See migration 176.',
        NEW.processor_key, COALESCE(v_miss, 'unknown');
END;
$function$

CREATE OR REPLACE FUNCTION public._get_canteen_history__by_name(p_camp_id uuid, p_camper text DEFAULT NULL::text, p_before text DEFAULT NULL::text, p_limit integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_mine   jsonb;
    v_ids    bigint[];
    v_staff  boolean := public.camp_staff_member(p_camp_id);
    v_rows   jsonb;
    v_limit  integer := LEAST(GREATEST(COALESCE(p_limit, 200), 1), 1000);
    v_want   bigint;         -- the one camper asked for, as an id
    v_key    text;           -- and as the key their ledger rows carry
BEGIN
    IF NOT v_staff THEN
        v_mine := public.camp_parent_campers(p_camp_id);
        IF jsonb_array_length(v_mine) = 0 THEN
            RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
        END IF;
        v_ids := public.camp_parent_camper_ids(p_camp_id);

        -- A parent may only page their own children. A p_camper outside their
        -- family is a refusal, not a filter — and it is now judged by id, so a
        -- renamed child is still theirs whichever spelling either side holds.
        IF p_camper IS NOT NULL THEN
            v_want := public.camp_person_by_name(p_camp_id, p_camper);
            IF NOT ((v_want IS NOT NULL AND v_want = ANY (v_ids))
                    OR v_mine ? p_camper) THEN
                RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
            END IF;
        END IF;
    ELSIF p_camper IS NOT NULL THEN
        v_want := public.camp_person_by_name(p_camp_id, p_camper);
    END IF;

    IF p_camper IS NOT NULL THEN
        v_key := public.canteen_account_key_for(p_camp_id, p_camper);
    END IF;

    SELECT COALESCE(jsonb_agg(x.payload || jsonb_build_object('sig', x.sig) ORDER BY x.tx_date DESC, x.first_seen DESC), '[]'::jsonb)
      INTO v_rows
      FROM (
        SELECT ct.payload, ct.sig, ct.tx_date, ct.first_seen
          FROM public.canteen_transactions ct
         WHERE ct.camp_id = p_camp_id
           -- One camper: by id where the row carries one, by the translated key
           -- otherwise. The translation is what reaches rows written before the
           -- rename.
           AND (p_camper IS NULL
                OR (v_want IS NOT NULL AND ct.camper_id = v_want::text)
                OR ct.camper = v_key
                OR ct.camper = p_camper)
           -- The family scope. A row with an id is judged on the id; a row
           -- without one falls back to the name, which is the 353 case.
           AND (v_staff
                OR (ct.camper_id IS NOT NULL
                    AND ct.camper_id ~ '^[0-9]+$'
                    AND ct.camper_id::bigint = ANY (v_ids))
                OR (ct.camper_id IS NULL AND v_mine ? ct.camper))
           AND (p_before IS NULL OR ct.tx_date < p_before)
         ORDER BY ct.tx_date DESC, ct.first_seen DESC
         LIMIT v_limit
      ) x;

    RETURN jsonb_build_object('success', true, 'transactions', v_rows);
END;
$function$

CREATE OR REPLACE FUNCTION public.add_payer_alias(p_camp_id uuid, p_family_key text, p_display_name text, p_normalized text, p_handle text DEFAULT ''::text, p_kind text DEFAULT 'zelle'::text, p_source text DEFAULT 'confirmed'::text, p_note text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_id uuid;
BEGIN
    IF NOT _deposit_can_admin(p_camp_id) THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
    END IF;
    IF COALESCE(p_normalized, '') = '' AND COALESCE(p_handle, '') = '' THEN
        RETURN jsonb_build_object('success', false, 'error', 'need_name_or_handle');
    END IF;

    INSERT INTO payer_aliases (camp_id, family_key, kind, display_name, normalized, handle, source, note, created_by)
    VALUES (p_camp_id, p_family_key, p_kind, COALESCE(p_display_name, ''),
            COALESCE(p_normalized, ''), COALESCE(p_handle, ''), p_source, COALESCE(p_note, ''), auth.uid())
    ON CONFLICT DO NOTHING
    RETURNING id INTO v_id;

    RETURN jsonb_build_object('success', true, 'aliasId', v_id,
                              'duplicate', v_id IS NULL);
END;
$function$

CREATE OR REPLACE FUNCTION public.camper_returns_as(p_camp_id uuid, p_name text, p_person_id bigint, p_confirm boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    caller  uuid := auth.uid();
    v_live  bigint;
    v_key   text;
    v_gone  record;
    v_moved jsonb;
    v_doc   jsonb;
BEGIN
    IF caller IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
    END IF;
    IF p_camp_id IS NULL OR NOT public._is_camp_admin(p_camp_id, caller) THEN
        RETURN jsonb_build_object('success', false, 'error', 'forbidden');
    END IF;

    -- The person enrolled under that spelling right now.
    SELECT person_id, source_key INTO v_live, v_key
      FROM camp_people
     WHERE camp_id = p_camp_id AND kind = 'camper' AND deleted_at IS NULL
       AND lower(btrim(source_key)) = lower(btrim(COALESCE(p_name, '')))
     LIMIT 1;
    IF v_live IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'no_live_camper_of_that_name');
    END IF;

    -- And the departed person they are said to be.
    SELECT person_id, source_key, deleted_at INTO v_gone
      FROM camp_people
     WHERE camp_id = p_camp_id AND kind = 'camper' AND person_id = p_person_id;
    IF v_gone.person_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'no_such_camper');
    END IF;
    IF v_gone.deleted_at IS NULL THEN
        -- Both enrolled. That is not a return, it is two children, and merging
        -- them would destroy one.
        RETURN jsonb_build_object('success', false, 'error', 'that_camper_is_still_enrolled',
            'detail', 'Person ' || p_person_id || ' (' || v_gone.source_key || ') is on the '
                   || 'roster now. A return means attaching to somebody who has LEFT.');
    END IF;
    IF v_live = p_person_id THEN
        RETURN jsonb_build_object('success', true, 'already', true, 'person_id', v_live);
    END IF;

    IF NOT p_confirm THEN
        RETURN jsonb_build_object(
            'success', true, 'dry_run', true,
            'would_merge', jsonb_build_object(
                'the_new_row', v_live, 'onto_the_returning_identity', p_person_id,
                'rows_that_would_move',
                    (SELECT count(*) FROM camp_canteen_accounts
                      WHERE camp_id = p_camp_id AND person_id = v_live)),
            'to_apply', 'SELECT public.camper_returns_as(''' || p_camp_id || '''::uuid, '
                     || quote_literal(p_name) || ', ' || p_person_id || ', true);');
    END IF;

    -- Move the new arrival's rows onto the identity they are returning to. This
    -- raises rather than half-moving if both hold a canteen account.
    v_moved := public._move_person_references(p_camp_id, v_live, p_person_id);

    -- One row for one person: the freshly minted one goes, and the returning one
    -- comes back under the spelling in use now.
    DELETE FROM camp_people
     WHERE camp_id = p_camp_id AND kind = 'camper' AND person_id = v_live;

    UPDATE camp_people
       SET source_key = v_key, name = v_key, deleted_at = NULL, updated_at = now()
     WHERE camp_id = p_camp_id AND kind = 'camper' AND person_id = p_person_id;

    -- And the document, or the next save undoes all of it.
    SELECT value INTO v_doc FROM camp_state_kv
     WHERE camp_id = p_camp_id AND key = 'app1' FOR UPDATE;
    IF v_doc IS NOT NULL
       AND jsonb_typeof(v_doc #> ARRAY['camperRoster', v_key]) = 'object' THEN
        UPDATE camp_state_kv
           SET value = jsonb_set(v_doc,
                         ARRAY['camperRoster', v_key, 'camperId'],
                         to_jsonb(p_person_id), true),
               updated_at = now()
         WHERE camp_id = p_camp_id AND key = 'app1';
    END IF;

    RETURN jsonb_build_object('success', true, 'merged', true,
                              'person_id', p_person_id, 'retired_row', v_live,
                              'references_moved', v_moved,
                              'document_updated', v_doc IS NOT NULL);
END;
$function$

CREATE OR REPLACE FUNCTION public.canteen_account_key_for(p_camp_id uuid, p_key text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_person bigint;
    v_key    text;
    v_holder bigint;
BEGIN
    IF p_camp_id IS NULL OR COALESCE(btrim(p_key), '') = '' THEN
        RETURN p_key;
    END IF;

    v_person := public.camp_person_by_name(p_camp_id, p_key);
    IF v_person IS NULL THEN
        RETURN p_key;
    END IF;

    SELECT a.account_key INTO v_key
      FROM camp_canteen_accounts a
     WHERE a.camp_id = p_camp_id AND a.person_id = v_person;
    IF v_key IS NOT NULL THEN
        RETURN v_key;
    END IF;

    -- This person has no account yet. The bare spelling is theirs to take —
    -- unless an account under it already belongs to SOMEBODY ELSE, which is a
    -- renamed or departed child's money. Then this child gets their own key.
    SELECT a.person_id INTO v_holder
      FROM camp_canteen_accounts a
     WHERE a.camp_id = p_camp_id AND a.account_key = p_key;
    IF v_holder IS NOT NULL AND v_holder <> v_person THEN
        RETURN p_key || ' #' || v_person;
    END IF;

    RETURN p_key;
END;
$function$

CREATE OR REPLACE FUNCTION public.canteen_office_cash_out(p_camp_id uuid, p_camper_name text, p_amount numeric, p_note text DEFAULT NULL::text, p_by text DEFAULT NULL::text, p_date text DEFAULT NULL::text, p_camper_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_id      bigint := p_camper_id;
    v_name    text;
    v_acct    jsonb;
    v_cfg     jsonb;
    v_amt     numeric;
    v_bal     numeric;
    v_floor   numeric;
    v_taken   numeric;
    v_max     numeric;          -- NULL means "no ceiling" (cashAllowNegative)
    v_dailym  numeric;
    v_left    numeric;
    v_note    text;
    v_date    text := COALESCE(NULLIF(btrim(p_date), ''),
                               (now() AT TIME ZONE 'utc')::date::text);
    now_ts    timestamptz := now();
BEGIN
    IF NOT public._canteen_office_may_edit(p_camp_id) THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
    END IF;

    v_amt  := round(COALESCE(p_amount, 0), 2);
    v_note := COALESCE(btrim(p_note), '');
    IF v_amt <= 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_amount');
    END IF;

    IF v_id IS NOT NULL THEN
        v_name := public.camp_person_name_for(p_camp_id, v_id);
        IF v_name IS NULL THEN
            RETURN jsonb_build_object('success', false, 'error', 'unknown_camper');
        END IF;
    ELSE
        v_name := NULLIF(btrim(COALESCE(p_camper_name, '')), '');
        IF v_name IS NULL THEN
            RETURN jsonb_build_object('success', false, 'error', 'missing_camper');
        END IF;
        v_id := public.camp_person_by_name(p_camp_id, v_name);
    END IF;

    v_cfg := public._canteen_cash_settings(p_camp_id);
    IF COALESCE((v_cfg ->> 'cashReasonRequired')::boolean, true) AND v_note = '' THEN
        RETURN jsonb_build_object('success', false, 'error', 'reason_required');
    END IF;

    -- The lock comes BEFORE the arithmetic, and holds to the end: the modal can
    -- sit open while a POS charge lands from another device, and the client's own
    -- re-validation reads a balance it cannot hold still.
    v_acct  := public.canteen_account_lock(p_camp_id, v_name);
    v_bal   := round(COALESCE((v_acct ->> 'balance')::numeric, 0), 2);
    v_floor := round(COALESCE((v_acct ->> 'balanceFloor')::numeric, 0), 2);
    v_taken := public._canteen_cash_taken_on(p_camp_id, v_name, v_date);

    -- SnacksCash.limit: cash draws physical money, so a CREDIT limit does not
    -- apply — credit exists to let someone finish a purchase, not to hand out
    -- cash. A balanceFloor does apply.
    IF COALESCE((v_cfg ->> 'cashAllowNegative')::boolean, false) THEN
        v_max := NULL;
    ELSE
        v_max := GREATEST(0, round(v_bal - v_floor, 2));
        IF v_max = 0 THEN
            RETURN jsonb_build_object('success', false, 'error', 'no_available_balance',
                'balance', v_bal, 'max', 0, 'takenToday', v_taken);
        END IF;
    END IF;

    v_dailym := round(COALESCE((v_cfg ->> 'cashDailyMax')::numeric, 0), 2);
    IF v_dailym > 0 THEN
        v_left := GREATEST(0, round(v_dailym - v_taken, 2));
        IF v_left = 0 THEN
            RETURN jsonb_build_object('success', false, 'error', 'daily_cash_limit_reached',
                'balance', v_bal, 'max', 0, 'takenToday', v_taken, 'cashDailyMax', v_dailym);
        END IF;
        IF v_max IS NULL OR v_left < v_max THEN v_max := v_left; END IF;
    END IF;

    IF v_max IS NOT NULL AND v_amt > v_max THEN
        RETURN jsonb_build_object('success', false, 'error', 'over_available',
            'balance', v_bal, 'max', v_max, 'takenToday', v_taken);
    END IF;

    v_bal := round(v_bal - v_amt, 2);

    -- spentToday is deliberately untouched: dailyLimit caps canteen SPENDING and
    -- cash out has its own cap. Same note as the browser version it replaces.
    PERFORM public.canteen_account_save(p_camp_id, v_name,
        COALESCE(v_acct, '{"dailyLimit":10,"spentToday":0}'::jsonb)
            || jsonb_build_object('balance', v_bal));

    -- SnacksCash.buildTransaction's shape, field for field. `kind:'cash_out'` is
    -- what lets revenue reporting and the drawer tell this from a sale, and is
    -- what _canteen_cash_taken_on counts.
    PERFORM public.canteen_post(p_camp_id, v_name,
        jsonb_build_object(
            'time',   to_char(now_ts, 'HH12:MI AM'),
            'camper', v_name,
            'items',  'Cash out' || CASE WHEN v_note <> '' THEN ' — ' || v_note ELSE '' END,
            'amount', v_amt,
            'type',   'debit',
            'kind',   'cash_out',
            'note',   v_note,
            'by',     COALESCE(btrim(p_by), ''),
            'date',   v_date
        ));

    RETURN jsonb_build_object('success', true, 'balance', v_bal,
                              'camper', v_name, 'camperId', v_id, 'amount', v_amt,
                              'takenToday', round(v_taken + v_amt, 2));
END;
$function$

CREATE OR REPLACE FUNCTION public.canteen_office_credit(p_camp_id uuid, p_camper_name text, p_amount numeric, p_method text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_date text DEFAULT NULL::text, p_camper_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_id     bigint := p_camper_id;
    v_name   text;
    v_acct   jsonb;
    v_bal    numeric;
    v_amt    numeric;
    v_date   text := COALESCE(NULLIF(btrim(p_date), ''),
                              (now() AT TIME ZONE 'utc')::date::text);
    now_ts   timestamptz := now();
BEGIN
    IF NOT public._canteen_office_may_edit(p_camp_id) THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
    END IF;

    -- NO UPPER BOUND, unlike the parent-facing submit_canteen_deposit's $500.
    -- That cap is there because the public can reach that function; this one is
    -- the desk recording cash it has already been handed, and a camp that takes
    -- a $600 season deposit must be able to record it.
    v_amt := round(COALESCE(p_amount, 0), 2);
    IF v_amt <= 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_amount');
    END IF;

    -- The label comes from the roster when an id was given, never from the name
    -- beside it — 231's rule, so a renamed camper's deposit still lands on their
    -- account rather than opening a second one under the old spelling.
    IF v_id IS NOT NULL THEN
        v_name := public.camp_person_name_for(p_camp_id, v_id);
        IF v_name IS NULL THEN
            RETURN jsonb_build_object('success', false, 'error', 'unknown_camper');
        END IF;
    ELSE
        v_name := NULLIF(btrim(COALESCE(p_camper_name, '')), '');
        IF v_name IS NULL THEN
            RETURN jsonb_build_object('success', false, 'error', 'missing_camper');
        END IF;
        v_id := public.camp_person_by_name(p_camp_id, v_name);
    END IF;

    v_acct := public.canteen_account_lock(p_camp_id, v_name);
    v_bal  := round(COALESCE((v_acct ->> 'balance')::numeric, 0) + v_amt, 2);

    PERFORM public.canteen_account_save(p_camp_id, v_name,
        COALESCE(v_acct, '{"dailyLimit":10,"spentToday":0}'::jsonb)
            || jsonb_build_object('balance', v_bal));

    -- The same row shape addDep built in the browser, so the ledger reads the
    -- same whichever path put the money on.
    PERFORM public.canteen_post(p_camp_id, v_name,
        jsonb_build_object(
            'time',   to_char(now_ts, 'HH12:MI AM'),
            'camper', v_name,
            'items',  'Deposit' || CASE WHEN COALESCE(btrim(p_note), '') <> ''
                                        THEN ' — ' || btrim(p_note) ELSE '' END,
            'amount', v_amt,
            'type',   'credit',
            'kind',   'deposit',
            'method', COALESCE(NULLIF(btrim(p_method), ''), 'cash'),
            'note',   COALESCE(btrim(p_note), ''),
            'date',   v_date
        ));

    RETURN jsonb_build_object('success', true, 'balance', v_bal,
                              'camper', v_name, 'camperId', v_id, 'amount', v_amt);
END;
$function$

CREATE OR REPLACE FUNCTION public.canteen_office_import_offline(p_camp_id uuid, p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    r          jsonb;
    v_oid      text;
    v_sig      text;
    v_id       bigint;
    v_name     text;
    v_key      text;
    v_amt      numeric;
    v_date     text;
    v_acct     jsonb;
    v_bal      numeric;
    v_spent    numeric;
    v_last     text;
    v_imported int := 0;
    v_dupes    int := 0;
    v_refused  jsonb := '[]'::jsonb;
    v_touched  jsonb := '{}'::jsonb;
BEGIN
    IF NOT public._canteen_office_may_edit(p_camp_id) THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
    END IF;
    IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_rows');
    END IF;
    IF jsonb_array_length(p_rows) > 1000 THEN
        RETURN jsonb_build_object('success', false, 'error', 'too_many_rows');
    END IF;

    FOR r IN SELECT value FROM jsonb_array_elements(p_rows) LOOP
        PERFORM public.clear_person_pins();   -- 257: each row starts clean
        -- Each row is refused on its own; one bad row does not lose the file.
        v_oid := NULLIF(btrim(COALESCE(r ->> 'id', '')), '');
        IF v_oid IS NULL THEN
            v_refused := v_refused || jsonb_build_object('id', NULL,
                'camper', r ->> 'camper', 'error', 'missing_id');
            CONTINUE;
        END IF;

        -- The register only ever writes debits. Anything else in the file is
        -- not a sale, and guessing what it meant is how money appears.
        IF COALESCE(r ->> 'type', '') <> 'debit' THEN
            v_refused := v_refused || jsonb_build_object('id', v_oid,
                'camper', r ->> 'camper', 'error', 'unsupported_type');
            CONTINUE;
        END IF;

        v_amt := round(COALESCE(NULLIF(r ->> 'amount', '')::numeric, 0), 2);
        -- The same ceiling the live purchase path has on one sale.
        IF v_amt <= 0 OR v_amt > 1000 THEN
            v_refused := v_refused || jsonb_build_object('id', v_oid,
                'camper', r ->> 'camper', 'error', 'invalid_amount');
            CONTINUE;
        END IF;

        v_date := btrim(COALESCE(r ->> 'date', ''));
        IF v_date !~ '^\d{4}-\d{2}-\d{2}$' THEN
            v_refused := v_refused || jsonb_build_object('id', v_oid,
                'camper', r ->> 'camper', 'error', 'invalid_date');
            CONTINUE;
        END IF;

        -- The PERSON first, the spelling only when the file predates ids —
        -- 240's order.
        v_id := NULL;
        IF COALESCE(r ->> 'camperId', '') ~ '^\d+$' THEN
            v_id := (r ->> 'camperId')::bigint;
            v_name := public.camp_person_name_for(p_camp_id, v_id);
            IF v_name IS NULL THEN
                v_refused := v_refused || jsonb_build_object('id', v_oid,
                    'camper', r ->> 'camper', 'error', 'unknown_camper');
                CONTINUE;
            END IF;
        ELSE
            v_name := NULLIF(btrim(COALESCE(r ->> 'camper', '')), '');
            IF v_name IS NULL THEN
                v_refused := v_refused || jsonb_build_object('id', v_oid,
                    'camper', NULL, 'error', 'missing_camper');
                CONTINUE;
            END IF;
            v_id := public.camp_person_by_name(p_camp_id, v_name);
        END IF;

        v_sig := 'offline:' || v_oid;

        -- Lock, THEN look. Two imports of one file serialize on the account, so
        -- the second one sees the first's row and moves nothing.
        v_acct := public.canteen_account_lock(p_camp_id, v_name);
        IF EXISTS (SELECT 1 FROM canteen_transactions
                    WHERE camp_id = p_camp_id AND sig = v_sig) THEN
            v_dupes := v_dupes + 1;
            CONTINUE;
        END IF;

        v_acct  := COALESCE(v_acct, '{"balance":0,"dailyLimit":10,"spentToday":0}'::jsonb);
        v_bal   := round(COALESCE((v_acct ->> 'balance')::numeric, 0) - v_amt, 2);
        v_spent := COALESCE((v_acct ->> 'spentToday')::numeric, 0);
        v_last  := v_acct ->> 'lastSpendDate';

        -- Today's cap has to know about today's offline sales, or the camper
        -- spends their limit twice: once offline, once again at the live till.
        -- An older sale is history for an older day and moves no counter.
        IF v_last IS NULL OR v_date > v_last THEN
            v_spent := v_amt;
            v_last  := v_date;
        ELSIF v_date = v_last THEN
            v_spent := round(v_spent + v_amt, 2);
        END IF;

        PERFORM public.canteen_account_save(p_camp_id, v_name,
            v_acct || jsonb_build_object('balance', v_bal,
                                         'spentToday', v_spent,
                                         'lastSpendDate', v_last));

        PERFORM public.canteen_post(p_camp_id, v_name,
            jsonb_build_object(
                'time',      COALESCE(r ->> 'time', ''),
                'camper',    v_name,
                'items',     COALESCE(r ->> 'items', ''),
                'amount',    v_amt,
                'type',      'debit',
                'kind',      'offline_sale',
                'offlineId', v_oid,
                'date',      v_date),
            v_sig);

        v_imported := v_imported + 1;
        v_key := public.canteen_account_key_for(p_camp_id, v_name);
        v_touched := v_touched || jsonb_build_object(v_key,
            jsonb_build_object('balance', v_bal, 'camperId', v_id));
    END LOOP;

    RETURN jsonb_build_object(
        'success',    true,
        'imported',   v_imported,
        'duplicates', v_dupes,
        'refused',    v_refused,
        'campers',    v_touched);
END;
$function$

CREATE OR REPLACE FUNCTION public.canteen_office_set_limit(p_camp_id uuid, p_camper_name text, p_daily_limit numeric, p_camper_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_id    bigint := p_camper_id;
    v_name  text;
    v_acct  jsonb;
    v_limit numeric;
BEGIN
    IF NOT public._canteen_office_may_edit(p_camp_id) THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
    END IF;

    -- 0 is MEANINGFUL, not blank: submit_canteen_purchase's convention is that
    -- dailyLimit <= 0 means no daily cap at all. setLimit in the browser used to
    -- reject it with `!amt` and so could never express "no limit"; that is fixed
    -- there and must not come back here.
    IF p_daily_limit IS NULL OR p_daily_limit < 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_limit');
    END IF;
    v_limit := round(p_daily_limit, 2);

    IF v_id IS NOT NULL THEN
        v_name := public.camp_person_name_for(p_camp_id, v_id);
        IF v_name IS NULL THEN
            RETURN jsonb_build_object('success', false, 'error', 'unknown_camper');
        END IF;
    ELSE
        v_name := NULLIF(btrim(COALESCE(p_camper_name, '')), '');
        IF v_name IS NULL THEN
            RETURN jsonb_build_object('success', false, 'error', 'missing_camper');
        END IF;
        v_id := public.camp_person_by_name(p_camp_id, v_name);
    END IF;

    v_acct := public.canteen_account_lock(p_camp_id, v_name);
    PERFORM public.canteen_account_save(p_camp_id, v_name,
        COALESCE(v_acct, '{"balance":0,"spentToday":0}'::jsonb)
            || jsonb_build_object('dailyLimit', v_limit));

    RETURN jsonb_build_object('success', true, 'dailyLimit', v_limit,
                              'camper', v_name, 'camperId', v_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.canteen_season_closeout(p_camp_id uuid, p_camper_id bigint, p_camper_name text, p_amount numeric, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_name  text := NULLIF(btrim(COALESCE(p_camper_name, '')), '');
    v_amt   numeric := round(COALESCE(p_amount, 0), 2);
    v_acct  jsonb;
    v_bal   numeric;
    v_ar    jsonb;
    v_note  text := COALESCE(NULLIF(btrim(COALESCE(p_note, '')), ''), 'Season close-out');
    now_ts  timestamptz := now();
BEGIN
    IF auth.uid() IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authenticated',
                                  'message', 'Not signed in.');
    END IF;
    IF NOT public.camp_staff_member(p_camp_id)
       OR COALESCE(public.user_section_level(p_camp_id, 'me.billing'), 'none') <> 'edit' THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authorized',
                                  'message', 'Only someone who can edit Billing can close out canteen money.');
    END IF;
    IF p_camper_id IS NOT NULL THEN
        -- The number decides, pinned for this call (257).
        v_name := public.camp_person_name_for(p_camp_id, p_camper_id);
        IF v_name IS NULL THEN
            RETURN jsonb_build_object('success', false, 'error', 'unknown_camper',
                                      'message', 'That child is not on this camp''s roster.');
        END IF;
    END IF;
    IF v_name IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'missing_camper', 'message', 'Which child?');
    END IF;
    IF v_amt <= 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_amount', 'message', 'Nothing to close out.');
    END IF;

    v_acct := public.canteen_account_lock(p_camp_id, v_name);
    IF v_acct IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'no_canteen_account',
                                  'message', 'This child has no canteen account.');
    END IF;
    v_bal := round(COALESCE(NULLIF(v_acct ->> 'balance', '')::numeric, 0), 2);
    -- The whole balance, never more — no till limit, no floor (TED-142/145).
    IF v_amt > v_bal THEN
        RETURN jsonb_build_object('success', false, 'error', 'over_balance', 'balance', v_bal,
            'message', 'Only $' || to_char(GREATEST(v_bal, 0), 'FM999999990.00') || ' is on the canteen account now — reopen the close-out to see the current figure.');
    END IF;

    v_bal := round(v_bal - v_amt, 2);
    v_acct := v_acct || jsonb_build_object('balance', v_bal);
    -- Auto-reload off (TED-143): the wallet is being emptied for the season.
    v_ar := v_acct -> 'autoReload';
    IF jsonb_typeof(v_ar) = 'object' AND COALESCE((v_ar ->> 'enabled')::boolean, false) THEN
        v_acct := jsonb_set(v_acct, '{autoReload}', v_ar || jsonb_build_object(
            'enabled', false,
            'disabledAt', to_char(now_ts, 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
            'disabledReason', 'switched off when the camp closed out the canteen balance for the season — switch it back on if you still want it'), true);
    END IF;
    PERFORM public.canteen_account_save(p_camp_id, v_name, v_acct);
    PERFORM public.canteen_post(p_camp_id, v_name,
        jsonb_build_object(
            'time',   to_char(now_ts, 'HH12:MI AM'),
            'camper', v_name,
            'items',  v_note,
            'amount', v_amt,
            'type',   'debit',
            'kind',   'closeout',
            'note',   v_note,
            'by',     'office (close-out)',
            'date',   to_char(now_ts, 'YYYY-MM-DD'),
            'timestamp', (extract(epoch FROM now_ts) * 1000)::bigint)
        || CASE WHEN p_camper_id IS NOT NULL THEN jsonb_build_object('camperId', p_camper_id) ELSE '{}'::jsonb END);
    RETURN jsonb_build_object('success', true, 'balance', v_bal, 'amount', v_amt, 'camper', v_name);
END $function$

CREATE OR REPLACE FUNCTION public.convert_family_ledgers(p_camp_id uuid, p_dry_run boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    caller     uuid := auth.uid();
    now_ts     timestamptz := now();
    v_me       jsonb;
    v_fams     jsonb;
    v_enr      jsonb;
    v_sess     jsonb;
    v_pays     jsonb;
    famRec     record;
    enrRec     record;
    v_fam      jsonb;
    v_entries  jsonb;
    v_camperIds jsonb;
    v_tuition  numeric;
    v_liveT    numeric;
    v_disc     numeric;
    v_seq      integer := 0;
    v_n_fams   integer := 0;
    v_report   jsonb := '[]'::jsonb;
    v_bal      numeric;
    e          jsonb;

    v_note text := 'converted from derived state by migration 171';
BEGIN
    IF caller IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
    END IF;
    IF NOT EXISTS (SELECT 1 FROM camps c WHERE c.id = p_camp_id AND c.owner = caller)
       AND NOT EXISTS (SELECT 1 FROM camp_users u
                        WHERE u.camp_id = p_camp_id AND u.user_id = caller
                          AND u.role IN ('owner', 'admin')) THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_permitted');
    END IF;

    IF p_dry_run THEN
        SELECT value INTO v_me FROM camp_state_kv
         WHERE camp_id = p_camp_id AND key = 'campistryMe';
    ELSE
        SELECT value INTO v_me FROM camp_state_kv
         WHERE camp_id = p_camp_id AND key = 'campistryMe';
    END IF;
    IF v_me IS NULL THEN
        RETURN jsonb_build_object('success', true, 'families', 0, 'note', 'no camp data');
    END IF;

    v_fams := public.camp_families_object(p_camp_id);
    v_enr  := COALESCE(v_me->'enrollments', '{}'::jsonb);
    v_sess := COALESCE(v_me->'sessions', '[]'::jsonb);
    v_pays := public.camp_payments_array(p_camp_id);

    FOR famRec IN SELECT key, value FROM jsonb_each(v_fams) LOOP
        v_fam := famRec.value;
        IF jsonb_typeof(v_fam) <> 'object' THEN CONTINUE; END IF;
        -- Already converted: never touch a real ledger.
        IF public.family_has_ledger(v_fam) THEN CONTINUE; END IF;

        v_entries := '[]'::jsonb;
        v_camperIds := CASE WHEN jsonb_typeof(v_fam->'camperIds') = 'array'
                            THEN v_fam->'camperIds' ELSE '[]'::jsonb END;

        -- ── tuition, one charge per live enrollment ──────────────────────
        FOR enrRec IN SELECT key, value FROM jsonb_each(v_enr) LOOP
            IF (enrRec.value->>'status') NOT IN ('enrolled', 'accepted') THEN CONTINUE; END IF;
            IF NOT (v_camperIds ? (enrRec.value->>'camperName')) THEN CONTINUE; END IF;

            v_liveT := (SELECT (s->>'tuition')::numeric
                          FROM jsonb_array_elements(v_sess) s
                         WHERE s->>'name' = enrRec.value->>'session' LIMIT 1);
            v_tuition := CASE WHEN v_liveT IS NOT NULL AND v_liveT > 0 THEN v_liveT
                              ELSE COALESCE((enrRec.value->>'sessionTuition')::numeric, 0) END;
            IF v_tuition IS NULL OR v_tuition <= 0 THEN CONTINUE; END IF;

            v_seq := v_seq + 1;
            v_entries := v_entries || jsonb_build_array(jsonb_build_object(
                'id', 'le_conv_' || famRec.key || '_' || v_seq,
                'kind', 'charge', 'amount', ROUND(v_tuition, 2), 'reason', 'tuition',
                'date', COALESCE(enrRec.value->>'date', to_char(now_ts, 'YYYY-MM-DD')),
                'postedAt', to_char(now_ts, 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
                'note', v_note, 'by', 'system',
                'source', jsonb_build_object(
                    'enrollmentId', enrRec.key,
                    'camperName', enrRec.value->>'camperName',
                    'camperId', enrRec.value->>'camperId',
                    'session', enrRec.value->>'session')
            ));

            v_disc := 0;
            IF enrRec.value->'discount' IS NOT NULL
               AND enrRec.value->'discount' <> 'null'::jsonb THEN
                v_disc := COALESCE((enrRec.value->'discount'->>'amt')::numeric, 0)
                        + ROUND(v_tuition * COALESCE((enrRec.value->'discount'->>'pct')::numeric, 0) / 100);
            END IF;
            IF v_disc > v_tuition THEN v_disc := v_tuition; END IF;
            IF v_disc > 0 THEN
                v_seq := v_seq + 1;
                v_entries := v_entries || jsonb_build_array(jsonb_build_object(
                    'id', 'le_conv_' || famRec.key || '_' || v_seq,
                    'kind', 'credit', 'amount', ROUND(v_disc, 2), 'reason', 'discount',
                    'date', COALESCE(enrRec.value->>'date', to_char(now_ts, 'YYYY-MM-DD')),
                    'postedAt', to_char(now_ts, 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
                    'note', v_note, 'by', 'system',
                    'source', jsonb_build_object('enrollmentId', enrRec.key)
                ));
            END IF;
        END LOOP;

        -- ── family charges and credits ────────────────────────────────────
        FOR e IN SELECT * FROM jsonb_array_elements(
                     CASE WHEN jsonb_typeof(v_fam->'charges') = 'array'
                          THEN v_fam->'charges' ELSE '[]'::jsonb END) LOOP
            IF COALESCE((e->>'amount')::numeric, 0) <= 0 THEN CONTINUE; END IF;
            v_seq := v_seq + 1;
            v_entries := v_entries || jsonb_build_array(jsonb_build_object(
                'id', 'le_conv_' || famRec.key || '_' || v_seq,
                'kind', 'charge', 'amount', ROUND((e->>'amount')::numeric, 2),
                'reason', 'fee',
                'date', COALESCE(e->>'date', to_char(now_ts, 'YYYY-MM-DD')),
                'postedAt', to_char(now_ts, 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
                'note', COALESCE(e->>'note', v_note), 'by', 'system',
                'source', jsonb_strip_nulls(jsonb_build_object('chargeId', e->>'id'))));
        END LOOP;

        FOR e IN SELECT * FROM jsonb_array_elements(
                     CASE WHEN jsonb_typeof(v_fam->'credits') = 'array'
                          THEN v_fam->'credits' ELSE '[]'::jsonb END) LOOP
            IF COALESCE((e->>'amount')::numeric, 0) <= 0 THEN CONTINUE; END IF;
            v_seq := v_seq + 1;
            v_entries := v_entries || jsonb_build_array(jsonb_build_object(
                'id', 'le_conv_' || famRec.key || '_' || v_seq,
                'kind', 'credit', 'amount', ROUND((e->>'amount')::numeric, 2),
                'reason', 'goodwill',
                'date', COALESCE(e->>'date', to_char(now_ts, 'YYYY-MM-DD')),
                'postedAt', to_char(now_ts, 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
                'note', COALESCE(e->>'note', v_note), 'by', 'system',
                'source', jsonb_strip_nulls(jsonb_build_object('creditId', e->>'id'))));
        END LOOP;

        -- ── payments, by familyKey. A refund is stored as a negative payment
        -- today, so it converts to a refund entry with a positive amount —
        -- rule 3: the sign lives in the kind.
        FOR e IN SELECT * FROM jsonb_array_elements(v_pays) LOOP
            IF COALESCE(e->>'familyKey', '') <> famRec.key THEN CONTINUE; END IF;
            IF COALESCE(e->>'status', '') IN ('pending', 'failed') THEN CONTINUE; END IF;
            IF COALESCE((e->>'amount')::numeric, 0) = 0 THEN CONTINUE; END IF;
            v_seq := v_seq + 1;
            v_entries := v_entries || jsonb_build_array(jsonb_build_object(
                'id', 'le_conv_' || famRec.key || '_' || v_seq,
                'kind', CASE WHEN (e->>'amount')::numeric < 0 THEN 'refund' ELSE 'payment' END,
                'amount', ROUND(ABS((e->>'amount')::numeric), 2),
                'reason', 'card',
                'date', COALESCE(e->>'date', to_char(now_ts, 'YYYY-MM-DD')),
                'postedAt', to_char(now_ts, 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
                'note', COALESCE(e->>'notes', v_note), 'by', 'system',
                'source', jsonb_build_object('paymentId', e->>'id')));
        END LOOP;

        -- ── bank deposits (Zelle/ACH), which never lived in the blob ──────
        -- The deposit id is carried on the entry (source.depositId, and the
        -- entry id itself). It was left empty originally, which meant a
        -- converted deposit could not be told apart from an unconverted one —
        -- so migration 178's ongoing poster would have posted it a SECOND time
        -- and credited the family twice. Conversion and ongoing posting now
        -- produce the same id for the same deposit, which is what makes "has
        -- this been posted?" have one answer.
        FOR e IN SELECT jsonb_build_object(
                     'id', d.id::text,
                     'amount', (d.amount_cents::numeric / 100),
                     'rev', d.is_reversal,
                     'date', to_char(d.created_at, 'YYYY-MM-DD')) AS j
                   FROM bank_deposits d
                  WHERE d.camp_id = p_camp_id AND d.status = 'posted'
                    AND d.family_key = famRec.key
        LOOP
            v_seq := v_seq + 1;
            v_entries := v_entries || jsonb_build_array(jsonb_build_object(
                'id', 'le_dep_' || (e->>'id'),
                'kind', CASE WHEN (e->>'rev')::boolean THEN 'refund' ELSE 'payment' END,
                'amount', ROUND(ABS((e->>'amount')::numeric), 2),
                'reason', 'zelle',
                'date', e->>'date',
                'postedAt', to_char(now_ts, 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
                'note', 'bank deposit — ' || v_note, 'by', 'system',
                'source', jsonb_build_object('depositId', e->>'id')));
        END LOOP;

        IF jsonb_array_length(v_entries) = 0 THEN CONTINUE; END IF;

        v_fam := jsonb_set(v_fam, '{entries}', v_entries, true);
        v_bal := public.family_ledger_balance(v_fam);
        v_n_fams := v_n_fams + 1;
        v_report := v_report || jsonb_build_array(jsonb_build_object(
            'famKey', famRec.key, 'name', v_fam->>'name',
            'entries', jsonb_array_length(v_entries), 'balance', v_bal));

        IF NOT p_dry_run THEN
            PERFORM public.camp_family_save(p_camp_id, famRec.key, v_fam);
        END IF;
    END LOOP;

    IF NOT p_dry_run AND v_n_fams > 0 THEN
    END IF;

    RETURN jsonb_build_object('success', true, 'dryRun', p_dry_run,
        'families', v_n_fams, 'detail', v_report);
END;
$function$

CREATE OR REPLACE FUNCTION public.credit_canteen_balance_from_stripe(p_camp_id uuid, p_camper_name text, p_amount numeric, p_payment_intent_id text, p_camper_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
        DECLARE
            v_camper text := p_camper_name;
        BEGIN
            -- 248: the camper's ID, when given, decides who this is. Resolved to
            -- their CURRENT name, which every writer maps to that person alone.
            IF p_camper_id IS NOT NULL THEN
                v_camper := public.camp_person_name_for((p_camp_id)::uuid, p_camper_id);
                IF v_camper IS NULL THEN
                    RETURN jsonb_build_object('success', false, 'error', 'unknown_camper');
                END IF;
            END IF;
            RETURN public._credit_canteen_balance_from_stripe__by_name(p_camp_id => p_camp_id, p_camper_name => v_camper, p_amount => p_amount, p_payment_intent_id => p_payment_intent_id);
        END;
        $function$

CREATE OR REPLACE FUNCTION public.delete_payer_alias(p_camp_id uuid, p_alias_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
