        'count',    jsonb_array_length(COALESCE(v_pays, '[]'::jsonb)));
END;
$function$

CREATE OR REPLACE FUNCTION public.get_canteen_accounts(p_camp_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_mine   jsonb;
    v_ids    bigint[];
    v_idtxt  text[];
    v_accts  jsonb := '{}'::jsonb;
    v_txs    jsonb;
    v_from   text := ((now() AT TIME ZONE 'utc')::date - 7)::text;
    v_cap    int  := 10000;
    v_total  bigint;
BEGIN
    -- Staff: the whole camp. Unchanged from 218 except where the ledger comes from.
    IF public.camp_staff_member(p_camp_id) THEN
        SELECT COALESCE(jsonb_object_agg(a.account_key, public._canteen_account_json(a)
                   || CASE WHEN a.person_id IS NULL THEN '{}'::jsonb
                           ELSE jsonb_build_object('camperId', a.person_id) END), '{}'::jsonb)
          INTO v_accts
          FROM camp_canteen_accounts a
         WHERE a.camp_id = p_camp_id AND a.deleted_at IS NULL;

        SELECT COALESCE(jsonb_agg(public._canteen_tx_json(t) ORDER BY t.tx_date DESC, t.first_seen DESC), '[]'::jsonb)
          INTO v_txs
          FROM (SELECT * FROM canteen_transactions
                 WHERE camp_id = p_camp_id AND tx_date >= v_from
                 ORDER BY tx_date DESC, first_seen DESC
                 LIMIT v_cap) t;

        SELECT count(*) INTO v_total FROM canteen_transactions
         WHERE camp_id = p_camp_id AND tx_date >= v_from;

        RETURN jsonb_build_object(
            'success', true,
            'accounts', v_accts,
            'transactions', v_txs,
            'ledgerWindow', jsonb_build_object(
                'from', v_from, 'rows', LEAST(v_total, v_cap), 'truncated', v_total > v_cap));
    END IF;

    v_mine := public.camp_parent_campers(p_camp_id);
    IF jsonb_array_length(v_mine) = 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
    END IF;

    -- The parent's children as IDS — 227's resolver, which reads the ids 223
    -- stamped on the invite, so a renamed child stays theirs. The NAMES above are
    -- only for accounts and rows that never had an id.
    v_ids := public.camp_parent_camper_ids(p_camp_id);
    SELECT COALESCE(array_agg(x::text), '{}') INTO v_idtxt FROM unnest(v_ids) x;

    SELECT COALESCE(jsonb_object_agg(a.account_key, public._canteen_account_json(a)
                   || CASE WHEN a.person_id IS NULL THEN '{}'::jsonb
                           ELSE jsonb_build_object('camperId', a.person_id) END), '{}'::jsonb)
      INTO v_accts
      FROM camp_canteen_accounts a
     WHERE a.camp_id = p_camp_id
       AND a.deleted_at IS NULL
       AND (
            (a.person_id IS NOT NULL AND a.person_id = ANY (v_ids))
            -- Only for rows with no id: once an account belongs to a child, a
            -- matching NAME must not grant anybody else sight of it.
            OR (a.person_id IS NULL AND v_mine ? a.account_key)
       );

    -- Their children's rows, by id; a row with no id only by the name it was
    -- written under, and only then — the same rule as the accounts above.
    SELECT COALESCE(jsonb_agg(public._canteen_tx_json(t) ORDER BY t.tx_date DESC, t.first_seen DESC), '[]'::jsonb)
      INTO v_txs
      FROM canteen_transactions t
     WHERE t.camp_id = p_camp_id
       AND (   (t.camper_id IS NOT NULL AND t.camper_id = ANY (v_idtxt))
            OR (t.camper_id IS NULL AND v_mine ? t.camper));

    RETURN jsonb_build_object('success', true, 'accounts', v_accts,
                              'transactions', v_txs, 'scope', 'parent');
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.get_my_balance_derived(p_camp_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    caller    uuid := auth.uid();
    inv       link_parent_invites;
    me        jsonb;
    enr       jsonb;
    fams      jsonb;
    pays      jsonb;
    sess_list jsonb;
    v_names   jsonb;
    rec       record;
    famRec    record;
    depRec    record;
    e         jsonb;
    p         jsonb;
    fam       jsonb;
    ch        jsonb;
    cr        jsonb;
    v_billed  numeric := 0;
    v_paid    numeric := 0;
    v_credits numeric := 0;
    v_tuition numeric;
    v_liveT   numeric;
    v_disc    numeric;
    v_amt     numeric;
    v_status  text;
    v_family  text;
    v_enrIds  jsonb := '[]'::jsonb;
    v_history jsonb := '[]'::jsonb;
    v_belongs boolean;
    v_famKey  text := NULL;          -- the PRIMARY family (card on file, plans)
    v_famKeys text[] := ARRAY[]::text[];   -- EVERY family this parent belongs to
    v_famNames text[] := ARRAY[]::text[];
    v_famName text := '';
    v_fam     jsonb := NULL;
    v_myEnr   jsonb := '[]'::jsonb;
    v_plans   jsonb;
    v_chargeable  boolean := false;
    v_processorKey text := NULL;
    v_cardLabel   text := NULL;
    v_blobStamp   timestamptz;   -- 205: the blob row's updated_at (cheap: no TOAST fetch)
    v_projStamp   timestamptz;   -- 205: what the projection was built from
BEGIN
    IF caller IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
    END IF;

    SELECT * INTO inv
    FROM link_parent_invites
    WHERE user_id = caller
      AND (status = 'active' OR billing_access = true)
      AND (expires_at IS NULL OR expires_at > now())
      AND (p_camp_id IS NULL OR camp_id = p_camp_id)
    ORDER BY created_at DESC
    LIMIT 1;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'no_active_invite');
    END IF;
    v_names := COALESCE(inv.camper_names, '[]'::jsonb);

    -- ★ 205: `me` is the same shape, assembled from indexed projections instead
    -- of the camp's whole jsonb value. Reading ANY field of campistryMe forces
    -- Postgres to detoast and parse the entire multi-megabyte value, so the cost
    -- was the camp's size on every parent's every balance check — measured at
    -- 828ms with 5 concurrent parents and 3575ms with 32, while every other
    -- portal read stayed under a second.
    --
    -- Selecting only updated_at does NOT fetch the TOASTed value, so the
    -- freshness probe is cheap. Stamps equal means the trigger has projected
    -- this exact blob; anything else (a camp never saved since this migration,
    -- a restored backup, a write that somehow bypassed the trigger) falls back
    -- to reading the blob, which is this function's own previous behaviour.
    -- Everything below this block is byte-identical to migration 166.
    SELECT updated_at INTO v_blobStamp FROM camp_state_kv
    WHERE camp_id = inv.camp_id AND key = 'campistryMe';
    SELECT blob_updated_at INTO v_projStamp FROM camp_billing_config
    WHERE camp_id = inv.camp_id;

    IF v_blobStamp IS NOT NULL AND v_projStamp IS NOT NULL AND v_projStamp = v_blobStamp THEN
        me := public.parent_billing_slice(inv.camp_id, v_names, inv.person_ids);
    ELSE
        SELECT value INTO me FROM camp_state_kv
        WHERE camp_id = inv.camp_id AND key = 'campistryMe';
    END IF;
    IF me IS NULL THEN me := '{}'::jsonb; END IF;
    enr       := COALESCE(me->'enrollments', '{}'::jsonb);
    fams      := COALESCE(public.camp_families_object(inv.camp_id), '{}'::jsonb);
    pays      := COALESCE(public.camp_payments_array(inv.camp_id), '[]'::jsonb);
    sess_list := COALESCE(me->'sessions', '[]'::jsonb);

    -- ─── tuition ───────────────────────────────────────────────────────────
    FOR rec IN SELECT key, value FROM jsonb_each(enr) LOOP
        e := rec.value;
        IF public._enrollment_is_parents(inv.camp_id, rec.key, e, v_names, inv.person_ids) AND (e->>'status') IN ('enrolled', 'accepted') THEN
            v_liveT := (SELECT (s->>'tuition')::numeric
                          FROM jsonb_array_elements(sess_list) s
                         WHERE s->>'name' = e->>'session'
                         LIMIT 1);
            v_tuition := CASE WHEN v_liveT IS NOT NULL AND v_liveT > 0 THEN v_liveT
                              ELSE COALESCE((e->>'sessionTuition')::numeric, 0) END;
            v_disc := 0;
            IF e->'discount' IS NOT NULL AND e->'discount' <> 'null'::jsonb THEN
                v_disc := COALESCE((e->'discount'->>'amt')::numeric, 0)
                        + ROUND(v_tuition * COALESCE((e->'discount'->>'pct')::numeric, 0) / 100);
            END IF;
            -- Never discount past free. campistry_me.js caps this; without the
            -- same cap here a flat discount bigger than the session price makes
            -- the parent's charge NEGATIVE while the camp's reads zero.
            IF v_disc > v_tuition THEN v_disc := v_tuition; END IF;
            v_billed := v_billed + (v_tuition - v_disc);
            v_enrIds := v_enrIds || to_jsonb(rec.key);
            v_myEnr := v_myEnr || jsonb_build_object(
                'id', rec.key, 'camperName', e->>'camperName',
                'session', e->>'session', 'net', v_tuition - v_disc
            );
        END IF;
    END LOOP;

    -- ─── which families are this parent's ──────────────────────────────────
    -- ALL of them, not just the first. A household split across two family
    -- records owes the sum of both; reporting one and hiding the other is how
    -- a parent ends up under-billed with no way to tell.
    FOR famRec IN SELECT key, value FROM jsonb_each(fams) ORDER BY key LOOP
        fam := famRec.value;
        v_belongs := EXISTS (
            SELECT 1 WHERE public._family_is_parents(inv.camp_id, famRec.key, fam, v_names, inv.person_ids)
        );
        IF NOT v_belongs THEN CONTINUE; END IF;

        v_famKeys := v_famKeys || famRec.key;
        IF COALESCE(fam->>'name', '') <> '' THEN
            v_famNames := v_famNames || (fam->>'name');
        END IF;

        -- The PRIMARY family is the first one, and is what card-on-file and
        -- payment plans are read from — those are per-family and cannot be
        -- summed. The BALANCE is the sum across all of them.
        IF v_famKey IS NULL THEN
            v_famKey  := famRec.key;
            v_fam     := fam;
            v_famName := COALESCE(fam->>'name', '');
        END IF;

        FOR ch IN SELECT * FROM jsonb_array_elements(COALESCE(fam->'charges', '[]'::jsonb)) LOOP
            v_amt := COALESCE((ch->>'amount')::numeric, 0);
            v_billed := v_billed + v_amt;
            v_history := v_history || jsonb_build_object(
                'date',   COALESCE(ch->>'date', ''),
                'desc',   COALESCE(NULLIF(ch->>'description', ''), COALESCE(ch->>'category', 'Charge')),
                'amt',    v_amt,
                'status', 'charge'
            );
        END LOOP;

        FOR cr IN SELECT * FROM jsonb_array_elements(COALESCE(fam->'credits', '[]'::jsonb)) LOOP
            v_amt := COALESCE((cr->>'amount')::numeric, 0);
            v_credits := v_credits + v_amt;
            v_history := v_history || jsonb_build_object(
                'date',   COALESCE(cr->>'date', ''),
                'desc',   COALESCE(NULLIF(cr->>'reason', ''), 'Credit'),
                'amt',    v_amt,
                'status', 'credit'
            );
        END LOOP;
    END LOOP;

    -- ─── payments from the blob ────────────────────────────────────────────
    FOR p IN SELECT * FROM jsonb_array_elements(pays) LOOP
        v_family := COALESCE(p->>'family', '');
        -- Match on the stored familyKey first (authoritative — every payment
        -- written by the app carries one), then any of this parent's family
        -- names, keeping the camper-name and enrollmentId paths for autopay and
        -- for older rows that carry neither.
        IF (v_names ? v_family)
           OR (v_enrIds ? COALESCE(p->>'enrollmentId', ''))
           OR (COALESCE(p->>'familyKey', '') <> '' AND COALESCE(p->>'familyKey', '') = ANY (v_famKeys))
           OR (v_family <> '' AND v_family = ANY (v_famNames))
        THEN
            v_amt := COALESCE((p->>'amount')::numeric, 0);
            v_status := COALESCE(p->>'status', '');
            -- Same exclusion as buildFamilyLedgers' _notCollected.
            IF v_status NOT IN ('pending', 'failed') THEN v_paid := v_paid + v_amt; END IF;
            v_history := v_history || jsonb_build_object(
                'date',   COALESCE(p->>'date', ''),
                'desc',   COALESCE(NULLIF(p->>'notes', ''), COALESCE(p->>'method', 'Payment')),
                'amt',    v_amt,
                'status', CASE WHEN v_amt < 0 THEN 'refunded'
                               WHEN v_status = 'pending' THEN 'pending'
                               WHEN v_status = 'failed' THEN 'failed'
                               ELSE 'paid' END
            );
        END IF;
    END LOOP;

    -- ─── Zelle / ACH deposits ──────────────────────────────────────────────
    -- The union migration 145 asked for. Read straight from bank_deposits
    -- rather than through get_camp_deposit_credits, which is admin-gated —
    -- this function is SECURITY DEFINER and scopes to the caller's own family
    -- keys, so a parent can only ever see deposits posted to their own family.
    --
    -- Rules copied exactly from get_camp_deposit_credits so the two sides
    -- cannot drift: posted only, family_key required, cents to dollars, and
    -- is_reversal flips the sign — a returned/NSF deposit has to DEBIT, or a
    -- family whose ACH bounced reads as paid.
    IF array_length(v_famKeys, 1) > 0 THEN
        FOR depRec IN
            SELECT id, family_key, amount_cents, is_reversal, deposit_date,
                   kind, payer_name, memo_code, trace_id
              FROM bank_deposits
             WHERE camp_id = inv.camp_id
               AND status = 'posted'
               AND family_key IS NOT NULL
               AND family_key = ANY (v_famKeys)
             ORDER BY deposit_date DESC NULLS LAST
        LOOP
            v_amt := (CASE WHEN depRec.is_reversal THEN -1 ELSE 1 END)
                     * ROUND(depRec.amount_cents::numeric / 100, 2);
            v_paid := v_paid + v_amt;
            v_history := v_history || jsonb_build_object(
                'date',   COALESCE(depRec.deposit_date::text, ''),
                'desc',   CASE
                            WHEN depRec.is_reversal AND depRec.payer_name <> ''
                                 THEN 'Returned / NSF — ' || depRec.payer_name
                            WHEN depRec.is_reversal THEN 'Returned / NSF'
                            WHEN depRec.payer_name <> '' AND depRec.memo_code <> ''
                                 THEN 'Received from ' || depRec.payer_name
                                      || ' (memo ' || depRec.memo_code || ')'
                            WHEN depRec.payer_name <> ''
                                 THEN 'Received from ' || depRec.payer_name
                            ELSE 'Bank deposit' END,
                'amt',    v_amt,
                'status', CASE WHEN depRec.is_reversal THEN 'refunded' ELSE 'paid' END
            );
        END LOOP;
    END IF;

    -- ─── per-family extras (not summable) ──────────────────────────────────
    IF v_fam IS NOT NULL AND v_fam ? 'plans' AND jsonb_typeof(v_fam->'plans') = 'array' THEN
        v_plans := v_fam->'plans';
    ELSIF v_fam IS NOT NULL AND v_fam ? 'plan' AND v_fam->'plan' <> 'null'::jsonb THEN
        v_plans := jsonb_build_array((v_fam->'plan') || jsonb_build_object('enrollmentIds', NULL));
    ELSE
        v_plans := '[]'::jsonb;
    END IF;

    -- Same shape as campistry_me.js's _famChargeable(f): a real vaulted BYOP
    -- token always wins; otherwise a Stripe customer + the cardOnFile flag.
    -- Only ever tells the client YES/NO + which processor — never returns
    -- the token/customer id itself.
    IF v_fam IS NOT NULL THEN
        IF v_fam->>'byopCustomerRef' IS NOT NULL AND v_fam->>'byopCustomerRef' <> '' THEN
            v_chargeable := true;
            v_processorKey := COALESCE(v_fam->>'byopProcessor', 'cardknox');
        ELSIF v_fam->>'stripeCustomerId' IS NOT NULL AND v_fam->>'stripeCustomerId' <> ''
              AND COALESCE((v_fam->>'cardOnFile')::boolean, false) THEN
            v_chargeable := true;
            v_processorKey := 'stripe';
        END IF;
        v_cardLabel := v_fam->>'paymentMethodLabel';
    END IF;

    RETURN jsonb_build_object(
        'success',            true,
        'camp_id',            inv.camp_id,
        'familyName',         COALESCE(v_names->>0, inv.parent_name),
        'campers',            v_names,
        'billed',             v_billed,
        'paid',               v_paid,
        'credits',            v_credits,
        'balance',            v_billed - v_paid - v_credits,
        'payments',           v_history,
        'familyKey',          v_famKey,
        -- Every family this balance covers, so the portal can say so when
        -- there is more than one rather than looking like it lost a record.
        'familyKeys',         to_jsonb(v_famKeys),
        'cardOnFile',         COALESCE(v_fam->'cardOnFile', 'false'::jsonb)::boolean,
        'paymentMethodType',  v_fam->>'paymentMethodType',
        'paymentMethodLabel', v_fam->>'paymentMethodLabel',
        'plans',              v_plans,
        'enrollments',        v_myEnr,
        'allowParentPaymentPlans', COALESCE((me #>> '{enrollSettings,allowParentPaymentPlans}')::boolean, false),
        'chargeable',         v_chargeable,
        'processorKey',       v_processorKey,
        'cardLabel',          v_cardLabel
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_my_saved_payment_methods(p_camp_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    caller   uuid := auth.uid();
    inv      link_parent_invites;
    v_names  jsonb;
    me       jsonb;
    fams     jsonb;
    famRec   record;
    v_famKey text := NULL;
    v_fam    jsonb := NULL;
    v_pm     jsonb;
    v_out    jsonb := '[]'::jsonb;
BEGIN
    IF caller IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
    END IF;

    SELECT * INTO inv
    FROM link_parent_invites
    WHERE user_id = caller
      AND (status = 'active' OR billing_access = true)
      AND (expires_at IS NULL OR expires_at > now())
      AND (p_camp_id IS NULL OR camp_id = p_camp_id)
    ORDER BY created_at DESC
    LIMIT 1;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'no_active_invite');
    END IF;
    v_names := COALESCE(inv.camper_names, '[]'::jsonb);

    SELECT value INTO me FROM camp_state_kv WHERE camp_id = inv.camp_id AND key = 'campistryMe';
    IF me IS NULL THEN me := '{}'::jsonb; END IF;
    -- ★ 212: live family ROWS, not the document's families branch.
    fams := public.camp_families_object(inv.camp_id);

    FOR famRec IN SELECT key, value FROM jsonb_each(fams) LOOP
        IF EXISTS (
            SELECT 1 WHERE public._family_is_parents(inv.camp_id, famRec.key, famRec.value, v_names, inv.person_ids)
        ) THEN
            v_famKey := famRec.key;
            v_fam := famRec.value;
            EXIT;
        END IF;
    END LOOP;

    IF v_fam IS NOT NULL THEN
        FOR v_pm IN SELECT * FROM jsonb_array_elements(COALESCE(v_fam->'savedPaymentMethods', '[]'::jsonb)) LOOP
            v_out := v_out || jsonb_build_object(
                'id',        v_pm->>'id',
                'type',      COALESCE(v_pm->>'type', 'card'),
                'processor', v_pm->>'processor',
                'last4',     v_pm->>'last4',
                'label',     v_pm->>'label',
                'addedDate', v_pm->>'addedDate',
                'isDefault', COALESCE((v_pm->>'isDefault')::boolean, false)
            );
        END LOOP;
    END IF;

    RETURN jsonb_build_object('success', true, 'familyKey', v_famKey, 'methods', v_out);
END;
$function$

CREATE OR REPLACE FUNCTION public.get_my_shop_orders(p_camp_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    caller   uuid := auth.uid();
    inv      link_parent_invites;
    v_value  jsonb;
    v_part   jsonb;
    v_orders jsonb := '[]'::jsonb;
    v_any    boolean := false;
BEGIN
    IF caller IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
    END IF;

    FOR inv IN
        SELECT * FROM link_parent_invites
        WHERE user_id = caller AND status = 'active'
          AND (expires_at IS NULL OR expires_at > now())
          AND (p_camp_id IS NULL OR camp_id = p_camp_id)
        ORDER BY created_at DESC
    LOOP
        v_any := true;

        SELECT value INTO v_value FROM camp_state_kv
        WHERE camp_id = inv.camp_id AND key = 'campistryShop';
        IF v_value IS NULL THEN CONTINUE; END IF;

        SELECT COALESCE(jsonb_agg(o || jsonb_build_object('campId', inv.camp_id)), '[]'::jsonb)
        INTO v_part
        FROM jsonb_array_elements(COALESCE(v_value->'orders', '[]'::jsonb)) AS o
        WHERE inv.camper_names IS NULL
           -- 233: the id the order was placed under, when it has one. This is
           -- what makes a rename invisible to the parent: the order keeps the
           -- old spelling and the invite has the new one, but both carry the
           -- same id.
           OR (NULLIF(o->>'camperId', '') IS NOT NULL
               AND public._invite_covers_person(inv.id, (o->>'camperId')::bigint))
           -- An order placed before 230 carries only a name. The wrapper resolves
           -- it and routes through the same gate, so this is not a second rule —
           -- it is the same rule reached by a longer road.
           OR (NULLIF(o->>'camperId', '') IS NULL
               AND public._invite_covers_camper(inv.id, COALESCE(o->>'camperName', '')));

        v_orders := v_orders || v_part;
    END LOOP;

    IF NOT v_any THEN
        RETURN jsonb_build_object('success', false, 'error', 'no_active_invite');
    END IF;

    RETURN jsonb_build_object('success', true, 'orders', v_orders);
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.get_payer_aliases(p_camp_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_out jsonb;
BEGIN
    IF NOT _deposit_can_admin(p_camp_id) THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
    END IF;

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
               'id', id, 'familyKey', family_key, 'kind', kind,
               'displayName', display_name, 'normalized', normalized,
               'handle', handle, 'source', source, 'note', note,
               'createdAt', created_at
           ) ORDER BY display_name), '[]'::jsonb)
      INTO v_out FROM payer_aliases WHERE camp_id = p_camp_id;

    RETURN jsonb_build_object('success', true, 'aliases', v_out);
END;
$function$

CREATE OR REPLACE FUNCTION public.get_public_form_config(p_camp_id uuid, p_kind text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    camp_row  record;
    kv_value  jsonb;
BEGIN
    IF p_kind NOT IN ('registration', 'staff') THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_kind');
    END IF;
    IF p_camp_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_payload');
    END IF;

    SELECT id, name INTO camp_row FROM camps WHERE id = p_camp_id;
    IF camp_row.id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'camp_not_found');
    END IF;

    SELECT value INTO kv_value
    FROM camp_state_kv
    WHERE camp_id = p_camp_id AND key = 'campistryMe';

    IF p_kind = 'registration' THEN
        RETURN jsonb_build_object(
            'success', true,
            'campName', camp_row.name,
            'formConfig', coalesce(kv_value -> 'formConfig', '{}'::jsonb),
            'sessions', coalesce(kv_value -> 'sessions', '[]'::jsonb),
            'sessionBundles', coalesce(kv_value -> 'sessionBundles', '[]'::jsonb),
            'promoCodes', coalesce(kv_value -> 'promoCodes', '{}'::jsonb),
            'schoolGrades', coalesce(kv_value #> '{bunkGenConfig,schoolGrades}', '[]'::jsonb),
            'allowParentPaymentPlans', coalesce(kv_value #> '{enrollSettings,allowParentPaymentPlans}', 'false'::jsonb),
            'depositPolicy', coalesce(kv_value #> '{enrollSettings,depositPolicy}', '{}'::jsonb),
            -- A fee a parent is not told about before they pick a card is both a
            -- card-brand violation and a chargeback waiting to happen.
            'cardFeePolicy', coalesce(kv_value #> '{enrollSettings,cardFeePolicy}', '{}'::jsonb)
        );
    ELSE
        RETURN jsonb_build_object(
            'success', true,
            'campName', camp_row.name,
            'staffFormConfig', coalesce(kv_value -> 'staffFormConfig', '{}'::jsonb),
            'sessions', coalesce(kv_value -> 'sessions', '[]'::jsonb)
        );
    END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.learn_template_from_correction(p_camp_id uuid, p_bank_signature text, p_template jsonb, p_template_hash text, p_is_shareable boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    -- Independent deposits that must yield identical rules before those rules
    -- are used on real mail.
    c_promote_at constant integer := 2;
    v_sig      text := lower(btrim(COALESCE(p_bank_signature, '')));
    v_seen     integer;
    v_taught   boolean;
    v_promoted boolean := false;
BEGIN
    IF NOT _deposit_can_admin(p_camp_id) THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
    END IF;
    IF v_sig = '' OR p_template IS NULL OR p_template->'fields' IS NULL
       OR p_template->'fields' = '{}'::jsonb OR COALESCE(p_template_hash, '') = '' THEN
        -- Nothing usable to learn from. Not an error: most corrections are on
        -- messages where the confirmed value does not appear verbatim.
        RETURN jsonb_build_object('success', true, 'learned', false);
    END IF;

    INSERT INTO bank_template_candidates (camp_id, bank_signature, template_hash, template)
    VALUES (p_camp_id, v_sig, p_template_hash, p_template)
    ON CONFLICT (camp_id, bank_signature, template_hash)
    DO UPDATE SET seen = bank_template_candidates.seen + 1,
                  last_seen_at = now()
    RETURNING seen INTO v_seen;

    SELECT EXISTS (
        SELECT 1 FROM bank_templates
         WHERE scope = 'camp' AND camp_id = p_camp_id
           AND bank_signature = v_sig AND source = 'taught'
    ) INTO v_taught;

    -- A camp that taught its own layout has said what its mail looks like.
    -- An inference does not get to argue with that.
    IF v_seen >= c_promote_at AND NOT v_taught THEN
        INSERT INTO bank_templates (
            camp_id, scope, bank_signature, bank_label,
            template, template_hash, is_shareable, source
        )
        VALUES (
            p_camp_id, 'camp', v_sig, v_sig,
            p_template, p_template_hash, COALESCE(p_is_shareable, false), 'auto'
        )
        ON CONFLICT (camp_id, bank_signature) WHERE scope = 'camp'
        DO UPDATE SET
            template      = EXCLUDED.template,
            template_hash = EXCLUDED.template_hash,
            is_shareable  = EXCLUDED.is_shareable,
            -- The counters described the rules being replaced, so they would
            -- misreport the new ones.
            hits = 0, misses = 0, conflicts = 0,
            updated_at    = now()
         WHERE bank_templates.source = 'auto'
           AND bank_templates.template_hash <> EXCLUDED.template_hash;

        UPDATE bank_template_candidates SET promoted_at = now()
         WHERE camp_id = p_camp_id AND bank_signature = v_sig
           AND template_hash = p_template_hash AND promoted_at IS NULL;
        v_promoted := true;
    END IF;

    RETURN jsonb_build_object(
        'success', true, 'learned', true,
        'seen', v_seen, 'promoteAt', c_promote_at,
        'promoted', v_promoted, 'blockedByTaught', v_taught
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.plan_due(p_fam jsonb, p_plan jsonb, p_as_of text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_dates jsonb;
    v_i     integer;
    v_due   text;
    v_bal   numeric;
    v_rem   integer;
    v_amt   numeric;
    v_fixed numeric;
BEGIN
    IF p_plan IS NULL OR jsonb_typeof(p_plan) <> 'object' THEN RETURN NULL; END IF;
    IF COALESCE((p_plan->>'paused')::boolean, false) THEN RETURN NULL; END IF;
    IF NOT COALESCE((p_plan->>'autopay')::boolean, true) THEN RETURN NULL; END IF;

    v_dates := CASE WHEN jsonb_typeof(p_plan->'dueDates') = 'array'
                    THEN p_plan->'dueDates' ELSE '[]'::jsonb END;
    v_i := COALESCE((p_plan->>'nextIndex')::integer, 0);
    IF v_i >= jsonb_array_length(v_dates) THEN RETURN NULL; END IF;

    v_due := v_dates->>v_i;
    IF v_due IS NULL OR (p_as_of IS NOT NULL AND v_due > p_as_of) THEN RETURN NULL; END IF;

    v_bal := public.family_ledger_balance(p_fam);
    v_rem := jsonb_array_length(v_dates) - v_i;

    -- Nothing owed: due nothing, and — crucially — destroy nothing.
    IF v_bal <= 0.005 THEN
        RETURN jsonb_build_object('index', v_i, 'dueDate', v_due,
                                  'amount', 0, 'remaining', v_rem,
                                  'reason', 'nothing_owed');
    END IF;

    -- The amount the office set for this instalment, when it set one (TED-068).
    IF jsonb_typeof(p_plan->'amounts') = 'array'
       AND jsonb_typeof(p_plan->'amounts'->v_i) = 'number' THEN
        v_fixed := (p_plan->'amounts'->>v_i)::numeric;
    END IF;

    IF v_fixed IS NOT NULL AND v_fixed > 0 THEN
        v_amt := LEAST(ROUND(v_fixed, 2), v_bal);
    ELSE
        -- The last instalment sweeps the remainder, so rounding cannot leave
        -- cents uncollectable at the end of every plan.
        v_amt := CASE WHEN v_rem <= 1 THEN v_bal ELSE ROUND(v_bal / v_rem, 2) END;
        IF v_amt > v_bal THEN v_amt := v_bal; END IF;
    END IF;

    RETURN jsonb_build_object('index', v_i, 'dueDate', v_due,
                              'amount', v_amt, 'remaining', v_rem);
END;
$function$

CREATE OR REPLACE FUNCTION public.remove_payment_method(p_camp_id uuid, p_method_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    caller    uuid := auth.uid();
    inv       link_parent_invites;
    v_names   jsonb;
    me        jsonb;
    fams      jsonb;
    famRec    record;
    v_famKey  text := NULL;
    v_fam     jsonb := NULL;
    v_pms     jsonb;
    v_new     jsonb := '[]'::jsonb;
    v_pm      jsonb;
    v_removed jsonb := NULL;
    v_wasDefault boolean := false;
    v_promote jsonb := NULL;
    now_ts    timestamptz := now();
BEGIN
    IF caller IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
    END IF;
    IF p_method_id IS NULL OR btrim(p_method_id) = '' THEN
        RETURN jsonb_build_object('success', false, 'error', 'missing_method_id');
    END IF;

    SELECT * INTO inv
    FROM link_parent_invites
    WHERE user_id = caller
      AND (status = 'active' OR billing_access = true)
      AND (expires_at IS NULL OR expires_at > now())
      AND (p_camp_id IS NULL OR camp_id = p_camp_id)
    ORDER BY created_at DESC
    LIMIT 1;
    IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'no_active_invite'); END IF;
    v_names := COALESCE(inv.camper_names, '[]'::jsonb);

    SELECT value INTO me FROM camp_state_kv WHERE camp_id = inv.camp_id AND key = 'campistryMe';
    IF me IS NULL THEN me := '{}'::jsonb; END IF;
    fams := public.camp_families_object(inv.camp_id);

    FOR famRec IN SELECT key, value FROM jsonb_each(fams) LOOP
        IF EXISTS (
            SELECT 1 WHERE public._family_is_parents(inv.camp_id, famRec.key, famRec.value, v_names, inv.person_ids)
        ) THEN
            v_famKey := famRec.key;
            v_fam := famRec.value;
            EXIT;
        END IF;
    END LOOP;

    IF v_fam IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'family_not_found');
    END IF;

    v_pms := COALESCE(v_fam->'savedPaymentMethods', '[]'::jsonb);
    FOR v_pm IN SELECT * FROM jsonb_array_elements(v_pms) LOOP
        IF v_pm->>'id' = p_method_id THEN
            v_removed := v_pm;
            v_wasDefault := COALESCE((v_pm->>'isDefault')::boolean, false);
        ELSE
            v_new := v_new || v_pm;
            IF v_promote IS NULL THEN v_promote := v_pm; END IF;
        END IF;
    END LOOP;

    IF v_removed IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'method_not_found');
    END IF;

    IF v_wasDefault AND v_promote IS NOT NULL THEN
        -- Re-run the array with the promoted entry flagged default, same
        -- shape set_default_payment_method produces.
        v_new := '[]'::jsonb;
        FOR v_pm IN SELECT * FROM jsonb_array_elements(v_pms) LOOP
            IF v_pm->>'id' = p_method_id THEN CONTINUE; END IF;
            IF v_pm->>'id' = v_promote->>'id' THEN
                v_new := v_new || jsonb_set(v_pm, '{isDefault}', 'true'::jsonb);
            ELSE
                v_new := v_new || jsonb_set(v_pm, '{isDefault}', 'false'::jsonb);
            END IF;
        END LOOP;
    END IF;

    v_fam := jsonb_set(v_fam, '{savedPaymentMethods}', v_new);

    IF v_wasDefault THEN
        IF v_promote IS NOT NULL THEN
            IF v_promote->>'processor' = 'cardknox' THEN
                v_fam := (v_fam - 'stripeCustomerId') - 'stripePaymentMethodId';
                v_fam := v_fam || jsonb_build_object(
                    'byopProcessor', 'cardknox',
                    'byopCustomerRef', v_promote->>'token',
                    'cardOnFile', true,
                    'paymentMethodType', COALESCE(v_promote->>'type', 'card'),
                    'paymentMethodLabel', v_promote->>'label'
                );
            ELSE
                v_fam := (v_fam - 'byopCustomerRef') - 'byopProcessor';
                v_fam := v_fam || jsonb_build_object(
                    'stripeCustomerId', v_promote->>'stripeCustomerId',
                    'stripePaymentMethodId', v_promote->>'token',
                    'cardOnFile', true,
                    'paymentMethodType', COALESCE(v_promote->>'type', 'card'),
                    'paymentMethodLabel', v_promote->>'label'
                );
            END IF;
        ELSE
            -- No methods left at all.
            v_fam := (v_fam - 'byopCustomerRef') - 'byopProcessor' - 'stripeCustomerId' - 'stripePaymentMethodId';
            v_fam := jsonb_set(v_fam, '{cardOnFile}', 'false'::jsonb, true);
        END IF;
    END IF;

    PERFORM public.camp_family_save(inv.camp_id, v_famKey, v_fam);

    RETURN jsonb_build_object('success', true, 'removedMethodId', p_method_id, 'newDefaultMethodId', CASE WHEN v_wasDefault THEN v_promote->>'id' ELSE NULL END);
END;
$function$

CREATE OR REPLACE FUNCTION public.report_plan_undercollection(p_camp_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    caller  uuid := auth.uid();
    v_me    jsonb;
    famRec  record;
    v_fam   jsonb;
    p       jsonb;
    i       jsonb;
    v_claimed numeric;
    v_paid    numeric;
    v_out   jsonb := '[]'::jsonb;
    v_total numeric := 0;
BEGIN
    IF caller IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
    END IF;
    IF NOT EXISTS (SELECT 1 FROM camps c WHERE c.id = p_camp_id AND c.owner = caller)
       AND NOT EXISTS (SELECT 1 FROM camp_users u
                        WHERE u.camp_id = p_camp_id AND u.user_id = caller
                          AND u.role IN ('owner', 'admin')) THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_permitted');
    END IF;

    SELECT value INTO v_me FROM camp_state_kv
     WHERE camp_id = p_camp_id AND key = 'campistryMe';
    IF v_me IS NULL THEN
        RETURN jsonb_build_object('success', true, 'families', 0);
    END IF;

    -- ★ 212: live family rows, in the same {key: payload} shape.
    FOR famRec IN SELECT key, value FROM jsonb_each(public.camp_families_object(p_camp_id)) LOOP
        v_fam := famRec.value;
        IF jsonb_typeof(v_fam) <> 'object' THEN CONTINUE; END IF;

        v_claimed := 0;
        FOR p IN SELECT * FROM jsonb_array_elements(
                     CASE WHEN jsonb_typeof(v_fam->'plans') = 'array' THEN v_fam->'plans'
                          WHEN jsonb_typeof(v_fam->'plan') = 'object'
                               THEN jsonb_build_array(v_fam->'plan')
                          ELSE '[]'::jsonb END) LOOP
            FOR i IN SELECT * FROM jsonb_array_elements(
                         CASE WHEN jsonb_typeof(p->'installments') = 'array'
                              THEN p->'installments' ELSE '[]'::jsonb END) LOOP
                -- An instalment marked paid but carrying the waiver note was
                -- never charged: that note is the fingerprint of the defect.
                IF COALESCE(i->>'status', '') = 'paid'
                   AND COALESCE(i->>'note', '') LIKE 'Covered by an earlier payment%' THEN
                    v_claimed := v_claimed + COALESCE((i->>'amount')::numeric, 0);
                END IF;
            END LOOP;
        END LOOP;

        IF v_claimed > 0 THEN
            SELECT COALESCE(SUM((e->>'amount')::numeric), 0) INTO v_paid
              FROM jsonb_array_elements(COALESCE(public.camp_payments_array(p_camp_id), '[]'::jsonb)) e
             WHERE e->>'familyKey' = famRec.key
               AND COALESCE(e->>'status', '') NOT IN ('pending', 'failed');

            v_total := v_total + v_claimed;
            v_out := v_out || jsonb_build_array(jsonb_build_object(
                'famKey', famRec.key, 'name', v_fam->>'name',
                'waivedNotCharged', ROUND(v_claimed, 2),
                'totalPaid', ROUND(v_paid, 2)));
        END IF;
    END LOOP;

    RETURN jsonb_build_object('success', true,
        'families', jsonb_array_length(v_out),
        'totalWaivedNotCharged', ROUND(v_total, 2),
        'detail', v_out);
END;
$function$

CREATE OR REPLACE FUNCTION public.resolve_bank_deposit(p_camp_id uuid, p_deposit_id uuid, p_family_key text, p_create_alias boolean DEFAULT true, p_alias_normalized text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_dep bank_deposits;
BEGIN
    IF NOT _deposit_can_admin(p_camp_id) THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
    END IF;

    SELECT * INTO v_dep FROM bank_deposits
     WHERE id = p_deposit_id AND camp_id = p_camp_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_found');
    END IF;

    UPDATE bank_deposits SET
        status      = 'posted',
        family_key  = p_family_key,
        matched_by  = 'staff',
        guardrail   = '',
        resolved_by = auth.uid(),
        resolved_at = now(),
        updated_at  = now()
     WHERE id = p_deposit_id;

    IF p_create_alias AND (COALESCE(p_alias_normalized, '') <> '' OR v_dep.payer_handle <> '') THEN
        INSERT INTO payer_aliases (camp_id, family_key, kind, display_name, normalized, handle, source, created_by)
        VALUES (p_camp_id, p_family_key, v_dep.kind, v_dep.payer_name,
                COALESCE(p_alias_normalized, ''), v_dep.payer_handle, 'learned', auth.uid())
        ON CONFLICT DO NOTHING;
    END IF;

    RETURN jsonb_build_object('success', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.resume_autopay_after_dispute(p_camp_id uuid, p_family_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_fam jsonb;
    v_new jsonb;
BEGIN
    IF auth.uid() IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_authenticated'); END IF;
    IF NOT public.camp_staff_member(p_camp_id)
       OR COALESCE(public.user_section_level(p_camp_id, 'me.billing'), 'none') <> 'edit' THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authorized',
                                  'message', 'Only someone who can edit Billing can resume autopay.');
    END IF;
    v_fam := public.camp_family_for_update(p_camp_id, p_family_key);
    IF v_fam IS NULL OR jsonb_typeof(v_fam) <> 'object' THEN
        RETURN jsonb_build_object('success', false, 'error', 'family_not_found');
    END IF;
    v_new := public._mark_plans_for_dispute(v_fam, NULL, false, NULL);
    IF v_new IS DISTINCT FROM v_fam THEN
        PERFORM public.camp_family_save(p_camp_id, p_family_key, v_new);
    END IF;
    RETURN jsonb_build_object('success', true, 'changed', v_new IS DISTINCT FROM v_fam);
END $function$

CREATE OR REPLACE FUNCTION public.set_canteen_auto_reload(p_camp_id uuid, p_camper_name text, p_config jsonb, p_camper_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_id       bigint := p_camper_id;
    v_name     text;
    v_locked_acct jsonb;
    caller       uuid := auth.uid();
    inv          link_parent_invites;
    v_value      jsonb;
    v_acct       jsonb;
    v_ar         jsonb;
    v_enabled    boolean;
    v_th_enabled boolean;
    v_th_amount  numeric;
    v_th_reload  numeric;
    v_sc_enabled boolean;
    v_sc_freq    text;
    v_sc_day     int;
    v_sc_reload  numeric;
    v_start_date text;
    v_stop_date  text;
    v_max_per_period  int;
    v_period_days     int;
    now_ts       timestamptz := now();
BEGIN
    IF caller IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
    END IF;
    IF COALESCE(btrim(p_camper_name), '') = '' AND v_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'missing_camper');
    END IF;
    IF p_config IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'missing_config');
    END IF;

    v_enabled    := COALESCE((p_config->>'enabled')::boolean, false);
    v_th_enabled := COALESCE((p_config->>'thresholdEnabled')::boolean, false);
    v_th_amount  := (p_config->>'thresholdAmount')::numeric;
    v_th_reload  := (p_config->>'thresholdReloadAmount')::numeric;
    v_sc_enabled := COALESCE((p_config->>'scheduleEnabled')::boolean, false);
    v_sc_freq    := p_config->>'scheduleFrequency';
    v_sc_day     := (p_config->>'scheduleDay')::int;
    v_sc_reload  := (p_config->>'scheduleReloadAmount')::numeric;
    v_start_date := NULLIF(btrim(COALESCE(p_config->>'startDate', '')), '');
    v_stop_date  := NULLIF(btrim(COALESCE(p_config->>'stopDate', '')), '');
    v_max_per_period := COALESCE((p_config->>'maxReloadsPerPeriod')::int, 1);
    v_period_days    := COALESCE((p_config->>'reloadPeriodDays')::int, 1);

    -- Validation -- same sane-bounds philosophy as set_canteen_limits (a bad
    -- client can't set nonsense). Reload amounts capped at $500/trigger,
    -- matching the existing $1-$500 manual-deposit range noted in migration 079.
    IF v_enabled AND NOT v_th_enabled AND NOT v_sc_enabled THEN
        RETURN jsonb_build_object('success', false, 'error', 'no_trigger_selected');
    END IF;
    IF v_th_enabled AND (v_th_amount IS NULL OR v_th_amount < 0 OR v_th_amount > 1000) THEN
        RETURN jsonb_build_object('success', false, 'error', 'bad_threshold_amount');
    END IF;
    IF v_th_enabled AND (v_th_reload IS NULL OR v_th_reload <= 0 OR v_th_reload > 500) THEN
        RETURN jsonb_build_object('success', false, 'error', 'bad_threshold_reload_amount');
    END IF;
    IF v_sc_enabled AND v_sc_freq NOT IN ('weekly', 'monthly') THEN
        RETURN jsonb_build_object('success', false, 'error', 'bad_schedule_frequency');
    END IF;
    IF v_sc_enabled AND v_sc_freq = 'weekly' AND (v_sc_day IS NULL OR v_sc_day < 0 OR v_sc_day > 6) THEN
        RETURN jsonb_build_object('success', false, 'error', 'bad_schedule_day');
    END IF;
    IF v_sc_enabled AND v_sc_freq = 'monthly' AND (v_sc_day IS NULL OR v_sc_day < 1 OR v_sc_day > 28) THEN
        RETURN jsonb_build_object('success', false, 'error', 'bad_schedule_day');
    END IF;
    IF v_sc_enabled AND (v_sc_reload IS NULL OR v_sc_reload <= 0 OR v_sc_reload > 500) THEN
        RETURN jsonb_build_object('success', false, 'error', 'bad_schedule_reload_amount');
    END IF;
    IF v_start_date IS NOT NULL AND v_start_date !~ '^\d{4}-\d{2}-\d{2}$' THEN
        RETURN jsonb_build_object('success', false, 'error', 'bad_start_date');
    END IF;
    IF v_stop_date IS NOT NULL AND v_stop_date !~ '^\d{4}-\d{2}-\d{2}$' THEN
        RETURN jsonb_build_object('success', false, 'error', 'bad_stop_date');
    END IF;
    -- Confirms each is a real calendar date (regex above only checks shape).
    BEGIN
        IF v_start_date IS NOT NULL THEN PERFORM v_start_date::date; END IF;
        IF v_stop_date IS NOT NULL THEN PERFORM v_stop_date::date; END IF;
    EXCEPTION WHEN OTHERS THEN
        RETURN jsonb_build_object('success', false, 'error', 'bad_date');
    END;
    IF v_start_date IS NOT NULL AND v_stop_date IS NOT NULL AND v_start_date::date > v_stop_date::date THEN
        RETURN jsonb_build_object('success', false, 'error', 'start_after_stop');
    END IF;
    IF v_max_per_period < 1 OR v_max_per_period > 20 THEN
        RETURN jsonb_build_object('success', false, 'error', 'bad_max_reloads_per_period');
    END IF;
    IF v_period_days < 1 OR v_period_days > 90 THEN
        RETURN jsonb_build_object('success', false, 'error', 'bad_reload_period_days');
    END IF;

    -- 224's gate, not another copy of the name-containment check. The invite that
    -- COVERS this child, preferring one that names them over the camp-wide
    -- wildcard, rather than whichever the parent created most recently.
    inv := public._parent_invite_for(p_camp_id, v_id, p_camper_name);
    IF inv.id IS NULL THEN
        -- Told apart, so a parent is not sent to the camp about a missing invite
        -- they do have.
        IF EXISTS (SELECT 1 FROM link_parent_invites
                    WHERE user_id = caller AND status = 'active'
                      AND (expires_at IS NULL OR expires_at > now())
                      AND (p_camp_id IS NULL OR camp_id = p_camp_id)) THEN
            RETURN jsonb_build_object('success', false, 'error', 'camper_not_on_invite');
        END IF;
        RETURN jsonb_build_object('success', false, 'error', 'no_active_invite');
    END IF;

    -- The label comes from the roster when an id was given, never from the name
    -- beside it.
    IF v_id IS NOT NULL THEN
        v_name := public.camp_person_name_for(inv.camp_id, v_id);
        IF v_name IS NULL THEN
            RETURN jsonb_build_object('success', false, 'error', 'unknown_camper');
        END IF;
    ELSE
        v_name := p_camper_name;
        v_id   := public.camp_person_by_name(inv.camp_id, v_name);
    END IF;


    -- 219: one camper's row, not the camp's document.
    v_value := NULL::jsonb;  -- document no longer read
    v_locked_acct := public.canteen_account_lock(inv.camp_id, v_name);

    v_acct := COALESCE(v_locked_acct, '{"balance":0,"dailyLimit":10,"spentToday":0}'::jsonb);
    v_ar   := COALESCE(v_acct->'autoReload', '{}'::jsonb);
    v_ar   := v_ar || jsonb_build_object(
        'enabled', v_enabled,
        'thresholdEnabled', v_th_enabled,
        'thresholdAmount', v_th_amount,
        'thresholdReloadAmount', v_th_reload,
        'scheduleEnabled', v_sc_enabled,
        'scheduleFrequency', v_sc_freq,
        'scheduleDay', v_sc_day,
        'scheduleReloadAmount', v_sc_reload,
        'startDate', v_start_date,
        'stopDate', v_stop_date,
        'maxReloadsPerPeriod', v_max_per_period,
        'reloadPeriodDays', v_period_days
    );
    -- Re-enabling clears a prior auto-disable-on-failures state -- a parent
    -- who just fixed/updated their card gets a clean slate, not an
    -- immediate re-disable on the next cron run's stale failure count.
    IF v_enabled THEN
        v_ar := (v_ar - 'lastFailureDate') - 'lastFailureReason';
        v_ar := jsonb_set(v_ar, '{consecutiveFailures}', '0'::jsonb, true);
    END IF;

    -- A parent's save: the camp's "why it was switched off" note goes (282).
    v_ar := (v_ar - 'disabledReason') - 'disabledAt';
    v_acct  := jsonb_set(v_acct, '{autoReload}', v_ar, true);
    PERFORM public.canteen_account_save(inv.camp_id, v_name,
        v_acct);

    RETURN jsonb_build_object(
        'success', true,
        'autoReload', v_ar,
        'cardOnFile', COALESCE((v_ar->>'cardOnFile')::boolean, false)
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.set_canteen_limits(p_camper_name text, p_daily_limit numeric DEFAULT NULL::numeric, p_credit_limit numeric DEFAULT NULL::numeric, p_balance_floor numeric DEFAULT NULL::numeric, p_camp_id uuid DEFAULT NULL::uuid, p_camper_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_id       bigint := p_camper_id;
    v_name     text;
    v_locked_acct jsonb;
    caller  uuid := auth.uid();
    inv     link_parent_invites;
    v_value jsonb;
    v_acct  jsonb;
    now_ts  timestamptz := now();
BEGIN
    IF caller IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
    END IF;
    IF COALESCE(btrim(p_camper_name), '') = '' AND v_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'missing_camper');
    END IF;
    -- Clamp to sane, non-negative bounds so a bad client can't set nonsense.
    IF p_daily_limit   IS NOT NULL AND (p_daily_limit   < 0 OR p_daily_limit   > 1000) THEN RETURN jsonb_build_object('success', false, 'error', 'bad_daily_limit');   END IF;
    IF p_credit_limit  IS NOT NULL AND (p_credit_limit  < 0 OR p_credit_limit  > 1000) THEN RETURN jsonb_build_object('success', false, 'error', 'bad_credit_limit');  END IF;
    IF p_balance_floor IS NOT NULL AND (p_balance_floor < 0 OR p_balance_floor > 1000) THEN RETURN jsonb_build_object('success', false, 'error', 'bad_balance_floor'); END IF;

    -- 224's gate, not another copy of the name-containment check. The invite that
    -- COVERS this child, preferring one that names them over the camp-wide
    -- wildcard, rather than whichever the parent created most recently.
    inv := public._parent_invite_for(p_camp_id, v_id, p_camper_name);
    IF inv.id IS NULL THEN
        -- Told apart, so a parent is not sent to the camp about a missing invite
        -- they do have.
        IF EXISTS (SELECT 1 FROM link_parent_invites
                    WHERE user_id = caller AND status = 'active'
                      AND (expires_at IS NULL OR expires_at > now())
                      AND (p_camp_id IS NULL OR camp_id = p_camp_id)) THEN
            RETURN jsonb_build_object('success', false, 'error', 'camper_not_on_invite');
        END IF;
        RETURN jsonb_build_object('success', false, 'error', 'no_active_invite');
    END IF;

    -- The label comes from the roster when an id was given, never from the name
    -- beside it.
    IF v_id IS NOT NULL THEN
        v_name := public.camp_person_name_for(inv.camp_id, v_id);
        IF v_name IS NULL THEN
            RETURN jsonb_build_object('success', false, 'error', 'unknown_camper');
        END IF;
    ELSE
        v_name := p_camper_name;
        v_id   := public.camp_person_by_name(inv.camp_id, v_name);
    END IF;


    -- 219: one camper's row, not the camp's document.
    v_value := NULL::jsonb;  -- document no longer read
    v_locked_acct := public.canteen_account_lock(inv.camp_id, v_name);

    v_acct := COALESCE(v_locked_acct, '{"balance":0,"dailyLimit":10,"spentToday":0}'::jsonb);
    IF p_daily_limit   IS NOT NULL THEN v_acct := jsonb_set(v_acct, '{dailyLimit}',   to_jsonb(p_daily_limit));   END IF;
    IF p_credit_limit  IS NOT NULL THEN v_acct := jsonb_set(v_acct, '{creditLimit}',  to_jsonb(p_credit_limit));  END IF;
    IF p_balance_floor IS NOT NULL THEN v_acct := jsonb_set(v_acct, '{balanceFloor}', to_jsonb(p_balance_floor)); END IF;

    PERFORM public.canteen_account_save(inv.camp_id, v_name,
        v_acct);

    RETURN jsonb_build_object('success', true,
        'dailyLimit',   v_acct->>'dailyLimit',
        'creditLimit',  v_acct->>'creditLimit',
        'balanceFloor', v_acct->>'balanceFloor');
END;
$function$

CREATE OR REPLACE FUNCTION public.set_card_fee_policy(p_camp_id uuid, p_policy jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    caller uuid := auth.uid();
    v_mode text;
    v_pol  jsonb;
BEGIN
    IF caller IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
    END IF;
    IF NOT EXISTS (SELECT 1 FROM camps c WHERE c.id = p_camp_id AND c.owner = caller) THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_owner');
    END IF;
    IF p_policy IS NULL OR jsonb_typeof(p_policy) <> 'object' THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_payload');
    END IF;

    v_mode := COALESCE(p_policy->>'mode', 'off');
    IF v_mode NOT IN ('off', 'surcharge', 'convenience', 'cash_discount') THEN
        RETURN jsonb_build_object('success', false, 'error', 'bad_mode');
    END IF;

    v_pol := p_policy
        -- 3% is Visa's ceiling; Mastercard allows 4, so a camp taking both is
        -- held to 3. Clamped rather than rejected, so a camp that types 5 gets a
        -- working policy at 3 instead of a failed save.
        || jsonb_build_object('surchargePct',
             least(3, greatest(0, COALESCE(NULLIF(p_policy->>'surchargePct','')::numeric, 0))))
        -- A percentage is not a convenience fee. There is nowhere to put one, so
        -- anything non-numeric or negative becomes zero.
        || jsonb_build_object('convenienceFlat',
             greatest(0, COALESCE(NULLIF(p_policy->>'convenienceFlat','')::numeric, 0)));

    -- jsonb_set with create_missing, one path, server-side: campistryMe has one
    -- writer (the browser, which rewrites the whole object), so a read-modify-
    -- write from anywhere else loses whatever was saved in between.
    INSERT INTO camp_state_kv (camp_id, key, value, updated_at)
    VALUES (p_camp_id, 'campistryMe',
            jsonb_build_object('enrollSettings', jsonb_build_object('cardFeePolicy', v_pol)), now())
    ON CONFLICT (camp_id, key) DO UPDATE
    SET value = jsonb_set(
            camp_state_kv.value,
            ARRAY['enrollSettings', 'cardFeePolicy'],
            v_pol,
            true
        ),
        updated_at = now();

    RETURN jsonb_build_object('success', true, 'policy', v_pol);
END;
$function$

CREATE OR REPLACE FUNCTION public.set_default_payment_method(p_camp_id uuid, p_method_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    caller    uuid := auth.uid();
    inv       link_parent_invites;
    v_names   jsonb;
    me        jsonb;
    fams      jsonb;
    famRec    record;
    v_famKey  text := NULL;
    v_fam     jsonb := NULL;
    v_pms     jsonb;
    v_new     jsonb := '[]'::jsonb;
    v_pm      jsonb;
    v_found   jsonb := NULL;
    now_ts    timestamptz := now();
BEGIN
    IF caller IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
    END IF;
    IF p_method_id IS NULL OR btrim(p_method_id) = '' THEN
        RETURN jsonb_build_object('success', false, 'error', 'missing_method_id');
    END IF;

    SELECT * INTO inv
    FROM link_parent_invites
    WHERE user_id = caller
      AND (status = 'active' OR billing_access = true)
      AND (expires_at IS NULL OR expires_at > now())
      AND (p_camp_id IS NULL OR camp_id = p_camp_id)
    ORDER BY created_at DESC
    LIMIT 1;
    IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'no_active_invite'); END IF;
    v_names := COALESCE(inv.camper_names, '[]'::jsonb);

    SELECT value INTO me FROM camp_state_kv WHERE camp_id = inv.camp_id AND key = 'campistryMe';
    IF me IS NULL THEN me := '{}'::jsonb; END IF;
    fams := public.camp_families_object(inv.camp_id);

    FOR famRec IN SELECT key, value FROM jsonb_each(fams) LOOP
        IF EXISTS (
            SELECT 1 WHERE public._family_is_parents(inv.camp_id, famRec.key, famRec.value, v_names, inv.person_ids)
        ) THEN
            v_famKey := famRec.key;
            v_fam := famRec.value;
            EXIT;
        END IF;
    END LOOP;

    IF v_fam IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'family_not_found');
    END IF;

    v_pms := COALESCE(v_fam->'savedPaymentMethods', '[]'::jsonb);
    FOR v_pm IN SELECT * FROM jsonb_array_elements(v_pms) LOOP
        IF v_pm->>'id' = p_method_id THEN
            v_found := v_pm;
            v_new := v_new || jsonb_set(v_pm, '{isDefault}', 'true'::jsonb);
        ELSE
            v_new := v_new || jsonb_set(v_pm, '{isDefault}', 'false'::jsonb);
        END IF;
    END LOOP;

    IF v_found IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'method_not_found');
    END IF;

    v_fam := jsonb_set(v_fam, '{savedPaymentMethods}', v_new);
    -- Sync the legacy single-slot fields so autopay and every charge path
    -- that doesn't pass an explicit paymentMethodId immediately picks this
    -- one up -- same fields cardknox-webhook/stripe-webhook already write.
    IF v_found->>'processor' = 'cardknox' THEN
        v_fam := (v_fam - 'stripeCustomerId') - 'stripePaymentMethodId';
        v_fam := v_fam || jsonb_build_object(
            'byopProcessor', 'cardknox',
            'byopCustomerRef', v_found->>'token',
            'cardOnFile', true,
            'paymentMethodType', COALESCE(v_found->>'type', 'card'),
            'paymentMethodLabel', v_found->>'label'
        );
    ELSE
        v_fam := (v_fam - 'byopCustomerRef') - 'byopProcessor';
        v_fam := v_fam || jsonb_build_object(
            'stripeCustomerId', v_found->>'stripeCustomerId',
            'stripePaymentMethodId', v_found->>'token',
            'cardOnFile', true,
            'paymentMethodType', COALESCE(v_found->>'type', 'card'),
            'paymentMethodLabel', v_found->>'label'
        );
    END IF;

    PERFORM public.camp_family_save(inv.camp_id, v_famKey, v_fam);

    RETURN jsonb_build_object('success', true, 'defaultMethodId', p_method_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.set_my_payment_plan(p_camp_id uuid, p_enrollment_ids jsonb, p_installments jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    caller     uuid := auth.uid();
    inv        link_parent_invites;
    v_names    jsonb;
    me         jsonb;
    enr        jsonb;
    fams       jsonb;
    sess_list  jsonb;
    pays       jsonb;
    rec        record;
    famRec     record;
    e          jsonb;
    fam        jsonb;
    ch         jsonb;
    cr         jsonb;
    p          jsonb;
    v_tuition  numeric;
    v_liveT    numeric;
    v_disc     numeric;
    v_amt      numeric;
    v_status   text;
    v_family   text;
    v_enrIds   jsonb := '[]'::jsonb;
    v_billed   numeric := 0;
    v_paid     numeric := 0;
    v_credits  numeric := 0;
    v_target   numeric := 0;
    v_belongs  boolean;
    v_famKey   text := NULL;
    v_fam      jsonb := NULL;
    v_count    integer := 0;
    v_sum      numeric := 0;
    inst       jsonb;
    v_dates    jsonb := '[]'::jsonb;
    v_n        integer := 0;
    v_total    numeric := 0;
    v_famName  text;
    v_existingPlans jsonb;
    v_newPlan  jsonb;
BEGIN
    IF caller IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
    END IF;
    IF p_camp_id IS NULL OR p_installments IS NULL OR jsonb_typeof(p_installments) <> 'array' THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_payload');
    END IF;

    SELECT * INTO inv
    FROM link_parent_invites
    WHERE user_id = caller
      AND (status = 'active' OR billing_access = true)
      AND (expires_at IS NULL OR expires_at > now())
      AND camp_id = p_camp_id
    ORDER BY created_at DESC
    LIMIT 1;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'no_active_invite');
    END IF;
    v_names := COALESCE(inv.camper_names, '[]'::jsonb);

    SELECT value INTO me FROM camp_state_kv
    WHERE camp_id = p_camp_id AND key = 'campistryMe';
    IF me IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'camp_not_found');
    END IF;

    IF NOT COALESCE((me #>> '{enrollSettings,allowParentPaymentPlans}')::boolean, false) THEN
        RETURN jsonb_build_object('success', false, 'error', 'self_serve_not_enabled');
    END IF;

    enr       := COALESCE(me->'enrollments', '{}'::jsonb);
    fams      := public.camp_families_object(p_camp_id);
    sess_list := COALESCE(me->'sessions', '[]'::jsonb);
    pays      := public.camp_payments_array(p_camp_id);

    -- Target = this family's real outstanding balance, computed exactly
    -- like get_my_balance does (billed - paid - credits) — never a sum of
    -- specific enrollments' tuition, which would ignore prior payments,
    -- family-level charges, and credits already on the ledger.
    FOR rec IN SELECT key, value FROM jsonb_each(enr) LOOP
        e := rec.value;
        IF public._enrollment_is_parents(inv.camp_id, rec.key, e, v_names, inv.person_ids) AND (e->>'status') IN ('enrolled', 'accepted') THEN
            v_liveT := (SELECT (s->>'tuition')::numeric FROM jsonb_array_elements(sess_list) s WHERE s->>'name' = e->>'session' LIMIT 1);
            v_tuition := CASE WHEN v_liveT IS NOT NULL AND v_liveT > 0 THEN v_liveT
                              ELSE COALESCE((e->>'sessionTuition')::numeric, 0) END;
            v_disc := 0;
            IF e->'discount' IS NOT NULL AND e->'discount' <> 'null'::jsonb THEN
                v_disc := COALESCE((e->'discount'->>'amt')::numeric, 0)
                        + ROUND(v_tuition * COALESCE((e->'discount'->>'pct')::numeric, 0) / 100);
            END IF;
            v_billed := v_billed + (v_tuition - v_disc);
            v_enrIds := v_enrIds || to_jsonb(rec.key);
        END IF;
    END LOOP;

    FOR famRec IN SELECT key, value FROM jsonb_each(fams) LOOP
        fam := famRec.value;
        v_belongs := EXISTS (
            SELECT 1 WHERE public._family_is_parents(inv.camp_id, famRec.key, fam, v_names, inv.person_ids)
        );
        IF NOT v_belongs THEN CONTINUE; END IF;
        IF v_famKey IS NULL THEN v_famKey := famRec.key; v_fam := fam; END IF;

        FOR ch IN SELECT * FROM jsonb_array_elements(COALESCE(fam->'charges', '[]'::jsonb)) LOOP
            v_billed := v_billed + COALESCE((ch->>'amount')::numeric, 0);
        END LOOP;
        FOR cr IN SELECT * FROM jsonb_array_elements(COALESCE(fam->'credits', '[]'::jsonb)) LOOP
            v_credits := v_credits + COALESCE((cr->>'amount')::numeric, 0);
        END LOOP;
    END LOOP;

    IF v_famKey IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'no_family_on_file');
    END IF;

    FOR p IN SELECT * FROM jsonb_array_elements(pays) LOOP
        v_family := COALESCE(p->>'family', '');
        IF (v_names ? v_family) OR (v_enrIds ? COALESCE(p->>'enrollmentId', '')) THEN
            v_amt := COALESCE((p->>'amount')::numeric, 0);
            v_status := COALESCE(p->>'status', '');
            IF v_status NOT IN ('pending', 'failed') THEN v_paid := v_paid + v_amt; END IF;
        END IF;
    END LOOP;

    v_target := v_billed - v_paid - v_credits;
    IF v_target <= 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'nothing_owed');
    END IF;

    -- Only one plan per family, full stop — reject if any plan already
    -- exists (per-camper or legacy whole-family), same as before.
    IF v_fam ? 'plans' AND jsonb_typeof(v_fam->'plans') = 'array' THEN
        v_existingPlans := v_fam->'plans';
    ELSIF v_fam ? 'plan' AND v_fam->'plan' <> 'null'::jsonb THEN
        v_existingPlans := jsonb_build_array(v_fam->'plan');
    ELSE
        v_existingPlans := '[]'::jsonb;
    END IF;
    IF jsonb_array_length(v_existingPlans) > 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'plan_already_exists');
    END IF;

    FOR inst IN SELECT * FROM jsonb_array_elements(p_installments) LOOP
        v_amt := COALESCE((inst->>'amount')::numeric, 0);
        IF v_amt <= 0 OR (inst->>'dueDate') IS NULL OR (inst->>'dueDate') = '' THEN CONTINUE; END IF;
        v_count := v_count + 1;
        v_sum := v_sum + v_amt;
    END LOOP;
    IF v_count < 1 OR v_count > 60 THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_installment_count');
    END IF;
    IF abs(v_sum - v_target) > 0.05 THEN
        RETURN jsonb_build_object('success', false, 'error', 'total_mismatch', 'expected', v_target, 'submitted', v_sum);
    END IF;

    FOR inst IN SELECT * FROM jsonb_array_elements(p_installments) ORDER BY (value->>'dueDate') LOOP
        v_amt := COALESCE((inst->>'amount')::numeric, 0);
        IF v_amt <= 0 OR (inst->>'dueDate') IS NULL OR (inst->>'dueDate') = '' THEN CONTINUE; END IF;
        v_n := v_n + 1;
        v_total := v_total + v_amt;
        -- The amount was required, and was just checked against the balance
        -- above. It is deliberately NOT stored: a frozen amount is a number
        -- that disagrees with reality later, which is the defect the derived
        -- model exists to remove. Only the date survives.
        v_dates := v_dates || jsonb_build_array(inst->>'dueDate');
    END LOOP;

    v_famName := coalesce(v_fam->>'name', v_names->>0, inv.parent_name, 'Family');
    -- The LEDGER shape (migration 172): when and how many, never how much.
    -- Field for field what BillingCore.newPlan() produces, because both are
    -- read by plan_due — which is what decides the amount, from the balance,
    -- at the moment of the charge.
    v_newPlan := jsonb_build_object(
        'id', 'plan_' || replace(gen_random_uuid()::text, '-', ''),
        'enrollmentIds', NULL,
        'dueDates', v_dates,
        'count', v_n,
        'nextIndex', 0,
        'history', '[]'::jsonb,
        'autopay', false,
        'paused', false,
        -- A snapshot of what was owed the day it was built, for display only.
        -- Never what gets charged.
        'total', round(v_total, 2),
        'createdAt', now()::text, 'source', 'parent'
    );
    -- ★ 215: BOTH mutations, on one family row, by hand rather than by rule.
    --
    -- The original set [key,'plans'] and then REMOVED the legacy [key,'plan'] on
    -- the accumulator before writing the whole branch. A rule matching only the
    -- first would have left the legacy singular 'plan' behind — a second plan the
    -- parent could still be charged on. So both are applied to the one row, in
    -- that order, and saved once.
    PERFORM public.camp_family_save(p_camp_id, v_famKey,
        jsonb_set(COALESCE(public.camp_family_for_update(p_camp_id, v_famKey), '{}'::jsonb),
                  ARRAY['plans'], jsonb_build_array(v_newPlan))
        #- ARRAY['plan']);


    INSERT INTO notifications (camp_id, source, source_id, title, body, link_target)
    VALUES (p_camp_id, 'parent_payment_plan_created', v_newPlan->>'id',
            'Family set up their own payment plan',
            v_famName || ' built a ' || v_n || '-payment plan (' || to_char(round(v_total,2), 'FM$999,999,990.00') || ' total) in Link.',
            'campistry_me.html')
    ON CONFLICT (camp_id, source, source_id) DO NOTHING;

    RETURN jsonb_build_object('success', true, 'plan', v_newPlan);
END;
$function$

CREATE OR REPLACE FUNCTION public.settle_shop_order(p_camp_id uuid, p_order_id text, p_pay_method text, p_total numeric, p_cancelled boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_locked_acct jsonb;
    now_ts       timestamptz := now();
    v_role       text;
    v_shop       jsonb;
    v_orders     jsonb;
    v_order      jsonb := NULL;
    v_idx        integer := NULL;
    i            integer;
    v_camper     text;
    v_camper_id  bigint;
    v_fam        jsonb;
    v_famKey     text := NULL;
    v_cur_method text := 'none';
    v_cur_amt    numeric := 0;
    v_new_method text;
    v_new_amt    numeric;
    v_delta      numeric;
    v_bal        numeric;
    v_charges    jsonb;
    v_kept       jsonb;
    c            jsonb;
    v_chargeId   text;
BEGIN
    -- ★ THE GATE, AND WHY IT IS THREE CONDITIONS AND NOT ONE.
    --
    -- This line used to read `p_camp_id IS NULL OR p_camp_id <> get_user_camp_id()`.
    -- For a caller who belongs to NO camp, get_user_camp_id() returns NULL, so
    -- `p_camp_id <> NULL` is NULL, `false OR NULL` is NULL, and `IF NULL THEN` does
    -- not fire. The function carried on. get_user_role() then answered 'viewer'
    -- (its own COALESCE default, never NULL), so the second check passed too, and
    -- the canteen branch below has no role list of its own.
    --
    -- Reproduced against a real Postgres: a signed-in user who owns nothing and is
    -- a member of nothing called settle_shop_order with another camp's id and an
    -- order id from that camp, and took $7 off a camper's canteen balance.
    --
    -- IS DISTINCT FROM closes it. camp_staff_member sits BESIDE it rather than
    -- instead of it, because it does not depend on the resolver at all: it asks
    -- whether this caller owns the camp or holds an accepted camp_users row. Every
    -- branch of get_user_camp_id already implies one of those, so no legitimate
    -- caller is newly refused — and if the resolver ever returns NULL again,
    -- membership is still required.
    IF p_camp_id IS NULL
       OR p_camp_id IS DISTINCT FROM get_user_camp_id()
       OR NOT camp_staff_member(p_camp_id) THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
    END IF;
    v_role := get_user_role();
    IF v_role IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
    END IF;

    v_new_method := CASE WHEN p_cancelled THEN 'none' ELSE COALESCE(p_pay_method, 'none') END;
    v_new_amt    := CASE WHEN p_cancelled THEN 0 ELSE round(COALESCE(p_total, 0), 2) END;
    IF v_new_amt < 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'negative_total');
    END IF;

    -- ── find the order ─────────────────────────────────────────────────────
    -- ── LOCK ORDER: campistryShop -> campistrySnacks -> campistryMe ────────
    -- Every SELECT below takes FOR UPDATE and holds it to the end of the
    -- function, because the shop write is read-modify-write on a JSONB blob.
    -- Without the lock two concurrent settlements — or a settlement racing a
    -- POS sale — both read the same document and the second write silently
    -- discards the first.
    SELECT value INTO v_shop FROM camp_state_kv
     WHERE camp_id = p_camp_id AND key = 'campistryShop'
     FOR UPDATE;
    IF v_shop IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'no_shop_data');
    END IF;
    v_orders := COALESCE(v_shop->'orders', '[]'::jsonb);

    FOR i IN 0 .. jsonb_array_length(v_orders) - 1 LOOP
        IF v_orders->i->>'id' = p_order_id THEN
            v_order := v_orders->i;
            v_idx := i;
            EXIT;
        END IF;
    END LOOP;
    IF v_order IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'order_not_found');
    END IF;

    v_camper := COALESCE(v_order->>'camperName', '');
    -- 233: WHO, not what they were called. 230 stamps camperId on every order
    -- it writes; an order placed before that carries only a name, so resolve it
    -- the same way everything else does and accept NULL when it cannot be
    -- resolved — the name paths below still answer for those.
    v_camper_id := NULLIF(v_order->>'camperId', '')::bigint;
    IF v_camper_id IS NULL AND v_camper <> '' THEN
        v_camper_id := public.camp_person_by_name(p_camp_id, v_camper);
    END IF;

    IF v_order->'settlement' IS NOT NULL AND v_order->'settlement' <> 'null'::jsonb THEN
        v_cur_method := COALESCE(v_order->'settlement'->>'method', 'none');
        v_cur_amt    := round(COALESCE((v_order->'settlement'->>'amount')::numeric, 0), 2);
    END IF;

    -- Nothing to do. This is the common case on a re-save and it must be free
    -- of side effects, or every edit to an unrelated field re-posts money.
    IF v_cur_method = v_new_method AND v_cur_amt = v_new_amt THEN
        RETURN jsonb_build_object('success', true, 'unchanged', true,
                                  'method', v_cur_method, 'amount', v_cur_amt);
    END IF;

    -- Posting to the family's bill is a billing action — a counselor running the
    -- shop must not be able to do it. The canteen path stays open to them,
    -- because taking canteen payment IS the job. (RLS is bypassed here by
    -- SECURITY DEFINER, so this check is the boundary, not a convenience.)
    IF (v_new_method = 'bill' OR v_cur_method = 'bill')
       AND v_role NOT IN ('owner', 'admin', 'manager') THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authorized_for_billing');
    END IF;

    -- ── canteen ────────────────────────────────────────────────────────────
    IF v_cur_method = 'canteen' OR v_new_method = 'canteen' THEN
        -- One camper's row, not the camp's document (219). The dead
        -- `v_snacks := NULL::jsonb` the transform left here, and the
        -- `IF v_snacks IS NULL` that followed it, are gone: assigning a variable
        -- nothing reads and then testing it is the exact shape that made four
        -- other canteen writers fail on every call for months.
        v_locked_acct := public.canteen_account_lock(p_camp_id, v_camper);

        -- How much MORE to take. Same method: just the difference. Method
        -- changed away from canteen: give all of it back. Changed to canteen:
        -- take the whole new amount.
        v_delta := (CASE WHEN v_new_method = 'canteen' THEN v_new_amt ELSE 0 END)
                 - (CASE WHEN v_cur_method = 'canteen' THEN v_cur_amt ELSE 0 END);

        IF v_delta <> 0 AND v_camper <> '' THEN
            v_bal := round(COALESCE((v_locked_acct->>'balance')::numeric, 0)
                           - v_delta, 2);
            PERFORM public.canteen_account_save(p_camp_id, v_camper,
                COALESCE(v_locked_acct, '{"dailyLimit":10,"spentToday":0}'::jsonb)
                    || jsonb_build_object('balance', v_bal));

            -- Append-only, because _reconcileBalances rebuilds every balance
            -- from this ledger. A positive delta is a debit; a negative one is
            -- money going back, which is a credit.
            PERFORM public.canteen_post(p_camp_id, v_camper,
                jsonb_build_object(
                    'time',   to_char(now_ts, 'HH12:MI AM'),
                    'camper', v_camper,
                    'items',  CASE WHEN v_delta > 0 THEN 'Camp Shop order'
                                   ELSE 'Camp Shop order — reversed' END,
                    'amount', abs(v_delta),
                    'type',   CASE WHEN v_delta > 0 THEN 'debit' ELSE 'credit' END,
                    'kind',   'shop',
                    'date',   to_char(now_ts, 'YYYY-MM-DD'),
                    'shopOrderId', p_order_id,
                    'timestamp', (extract(epoch from now_ts) * 1000)::bigint
                ));
        END IF;
    END IF;

    -- ── camp bill ──────────────────────────────────────────────────────────
    IF v_cur_method = 'bill' OR v_new_method = 'bill' THEN
        -- 233: the shared rule, on the id first. This is the line that used to
        -- be `WHERE ci = v_camper` and answered no_family_for_camper for a child
        -- who was in a family under the spelling they were enrolled with.
        v_famKey := public.camp_family_key_for_person(p_camp_id, v_camper_id, v_camper);

        IF v_famKey IS NULL AND v_new_method = 'bill' THEN
            -- Still refuse — 167 added this so a sweatshirt could not go
            -- unbilled — but now it means what it says: no family lists this
            -- child under any spelling, and no family holds their id.
            RETURN jsonb_build_object('success', false, 'error', 'no_family_for_camper',
                'detail', 'No family record lists ' || v_camper ||
                          '. Add them to a family before charging the camp bill.',
                'camperId', v_camper_id);
        END IF;

        IF v_famKey IS NOT NULL THEN
            v_chargeId := 'shop_' || p_order_id;
            -- The real signatures — see 233. camp_family_for_update takes
            -- (camp, key) and returns the whole locked payload; the field-scoped
            -- 3-argument form 214's transform wrote here was never created.
            v_fam      := public.camp_family_for_update(p_camp_id, v_famKey);
            IF v_fam IS NULL OR jsonb_typeof(v_fam) <> 'object' THEN
                RETURN jsonb_build_object('success', false, 'error', 'family_not_found');
            END IF;
            v_charges  := COALESCE(v_fam->'charges', '[]'::jsonb);

            -- Drop any previous charge for this order, then re-add at the new
            -- amount. A SET, not an append — re-settling must replace, never
            -- stack a second sweatshirt onto the family's balance.
            v_kept := '[]'::jsonb;
            FOR c IN SELECT * FROM jsonb_array_elements(v_charges) LOOP
                IF COALESCE(c->>'id', '') <> v_chargeId THEN
                    v_kept := v_kept || jsonb_build_array(c);
                END IF;
            END LOOP;

            IF v_new_method = 'bill' AND v_new_amt > 0 THEN
                v_kept := v_kept || jsonb_build_array(jsonb_build_object(
                    'id',          v_chargeId,
                    'category',    'Camp Shop',
                    'description', 'Camp Shop order' ||
                                   CASE WHEN v_camper <> '' THEN ' — ' || v_camper ELSE '' END,
                    'amount',      v_new_amt,
                    'date',        to_char(now_ts, 'YYYY-MM-DD'),
                    'shopOrderId', p_order_id,
                    'timestamp',   (extract(epoch from now_ts) * 1000)::bigint
                ));
            END IF;

            PERFORM public.camp_family_save(p_camp_id, v_famKey,
                        public._sync_charge_to_ledger(v_fam || jsonb_build_object('charges', v_kept), v_chargeId));
        END IF;
    END IF;

    -- ── record what was taken ──────────────────────────────────────────────
    v_order := v_order || jsonb_build_object(
        'settlement', jsonb_build_object(
            'method',   v_new_method,
            'amount',   v_new_amt,
            'familyKey', v_famKey,
            'at',       to_char(now_ts, 'YYYY-MM-DD"T"HH24:MI:SS"Z"')),
        -- The id this settlement was decided on, so a later re-settle or a
        -- dispute does not have to re-derive it from a name that may have moved
        -- on again.
        'camperId', COALESCE(to_jsonb(v_camper_id), v_order->'camperId'),
        -- 'paid' means the money is actually in. Cash/cheque/card are collected
        -- outside Campistry, so the office ticks those by hand; the two methods
        -- this function settles are paid by definition once posted.
        'paid', CASE WHEN v_new_method IN ('canteen', 'bill') THEN true
                     ELSE COALESCE((v_order->>'paid')::boolean, false) END
    );

    v_shop := jsonb_set(v_shop, ARRAY['orders', v_idx::text], v_order, true);
    UPDATE camp_state_kv SET value = v_shop, updated_at = now_ts
     WHERE camp_id = p_camp_id AND key = 'campistryShop';

    RETURN jsonb_build_object('success', true,
        'method', v_new_method, 'amount', v_new_amt,
        'previousMethod', v_cur_method, 'previousAmount', v_cur_amt,
        'familyKey', v_famKey, 'camperId', v_camper_id, 'balance', v_bal);
END;
$function$

CREATE OR REPLACE FUNCTION public.submit_canteen_deposit(p_camper_name text, p_amount numeric, p_camp_id uuid DEFAULT NULL::uuid, p_camper_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_id       bigint := p_camper_id;
    v_name     text;
    v_locked_acct jsonb;
    caller  uuid := auth.uid();
    inv     link_parent_invites;
    v_value jsonb;
    v_bal   numeric;
    now_ts  timestamptz := now();
BEGIN
    IF caller IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
    END IF;
    IF COALESCE(btrim(p_camper_name), '') = '' AND v_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'missing_camper');
    END IF;
    IF p_amount IS NULL OR p_amount < 1 OR p_amount > 500 THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_amount');
    END IF;

    -- 224's gate, not another copy of the name-containment check. The invite that
    -- COVERS this child, preferring one that names them over the camp-wide
    -- wildcard, rather than whichever the parent created most recently.
    inv := public._parent_invite_for(p_camp_id, v_id, p_camper_name);
    IF inv.id IS NULL THEN
        -- Told apart, so a parent is not sent to the camp about a missing invite
        -- they do have.
        IF EXISTS (SELECT 1 FROM link_parent_invites
                    WHERE user_id = caller AND status = 'active'
                      AND (expires_at IS NULL OR expires_at > now())
                      AND (p_camp_id IS NULL OR camp_id = p_camp_id)) THEN
            RETURN jsonb_build_object('success', false, 'error', 'camper_not_on_invite');
        END IF;
        RETURN jsonb_build_object('success', false, 'error', 'no_active_invite');
    END IF;

    -- The label comes from the roster when an id was given, never from the name
    -- beside it.
    IF v_id IS NOT NULL THEN
        v_name := public.camp_person_name_for(inv.camp_id, v_id);
        IF v_name IS NULL THEN
            RETURN jsonb_build_object('success', false, 'error', 'unknown_camper');
        END IF;
    ELSE
        v_name := p_camper_name;
        v_id   := public.camp_person_by_name(inv.camp_id, v_name);
    END IF;


    -- 219: one camper's row, not the camp's document.
    v_value := NULL::jsonb;  -- document no longer read
    v_locked_acct := public.canteen_account_lock(inv.camp_id, v_name);


    v_bal := round(COALESCE((v_locked_acct->>'balance')::numeric, 0) + p_amount, 2);

    PERFORM public.canteen_account_save(inv.camp_id, v_name,
        COALESCE(v_locked_acct, '{"dailyLimit":10,"spentToday":0}'::jsonb)
            || jsonb_build_object('balance', v_bal));

    PERFORM public.canteen_post(inv.camp_id, v_name,
        jsonb_build_object(
            'time',   to_char(now_ts, 'HH12:MI AM'),
            'camper', v_name,
            'items',  'Funds added by parent',
            'amount', p_amount,
            'type',   'credit',
            'date',   to_char(now_ts, 'YYYY-MM-DD')
        ));


    RETURN jsonb_build_object('success', true, 'balance', v_bal);
END;
$function$

CREATE OR REPLACE FUNCTION public.submit_canteen_purchase_once(p_camp_id uuid, p_sale_key text, p_camper_name text, p_amount numeric, p_items text DEFAULT ''::text, p_date date DEFAULT NULL::date, p_camper_id bigint DEFAULT NULL::bigint, p_sold jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_key  text := NULLIF(btrim(COALESCE(p_sale_key, '')), '');
    v_fp   text := COALESCE(p_camper_id::text, 'n:' || btrim(COALESCE(p_camper_name, ''))) || '|' || round(COALESCE(p_amount, 0), 2)::text;
    v_n    integer := 0;
    v_prev public.canteen_sale_keys%ROWTYPE;
    v_sold jsonb;
    r      jsonb;
BEGIN
    IF auth.uid() IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_authenticated'); END IF;
    IF p_camp_id IS NULL OR NOT public.camp_staff_member(p_camp_id) THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
    END IF;

    -- What was sold, cleaned: [{id, qty}] with a whole quantity 1..100.
    IF jsonb_typeof(p_sold) = 'array' THEN
        SELECT COALESCE(jsonb_agg(jsonb_build_object('id', x -> 'id', 'qty', floor((x ->> 'qty')::numeric))), '[]'::jsonb)
          INTO v_sold
          FROM jsonb_array_elements(p_sold) x
         WHERE jsonb_typeof(x) = 'object' AND x ? 'id' AND jsonb_typeof(x -> 'qty') = 'number'
           AND floor((x ->> 'qty')::numeric) BETWEEN 1 AND 100;
    END IF;

    IF v_key IS NOT NULL THEN
        -- A few days is all a retry ever needs.
        DELETE FROM canteen_sale_keys WHERE camp_id = p_camp_id AND created_at < now() - interval '3 days';
        INSERT INTO canteen_sale_keys (camp_id, sale_key, fingerprint) VALUES (p_camp_id, v_key, v_fp)
            ON CONFLICT (camp_id, sale_key) DO NOTHING;
        GET DIAGNOSTICS v_n = ROW_COUNT;
        IF v_n = 0 THEN
            SELECT * INTO v_prev FROM canteen_sale_keys WHERE camp_id = p_camp_id AND sale_key = v_key;
            IF v_prev.fingerprint IS DISTINCT FROM v_fp THEN
                RETURN jsonb_build_object('success', false, 'error', 'sale_key_reused');
            END IF;
            IF v_prev.result IS NOT NULL THEN
                RETURN v_prev.result || jsonb_build_object('replayed', true);
            END IF;
            RETURN jsonb_build_object('success', false, 'error', 'sale_in_progress');
        END IF;
    END IF;

    r := public.submit_canteen_purchase(p_camp_id, p_camper_name, p_amount, p_items, p_date, p_camper_id);
    IF COALESCE((r ->> 'success')::boolean, false) THEN
        -- The sale's own line: posted by this call, in this transaction, under
        -- the child's wallet lock (first_seen is this transaction's clock).
        IF v_sold IS NOT NULL AND jsonb_array_length(v_sold) > 0 THEN
            UPDATE canteen_transactions
               SET payload = payload || jsonb_build_object('soldItems', v_sold)
             WHERE camp_id = p_camp_id AND first_seen = now() AND tx_type = 'debit'
               AND amount = p_amount AND NOT (payload ? 'kind');
        END IF;
        IF v_key IS NOT NULL THEN
            UPDATE canteen_sale_keys SET result = r WHERE camp_id = p_camp_id AND sale_key = v_key;
        END IF;
    ELSIF v_key IS NOT NULL THEN
        -- Nothing was charged: the same sale may be tried again.
        DELETE FROM canteen_sale_keys WHERE camp_id = p_camp_id AND sale_key = v_key;
    END IF;
    RETURN r;
END $function$

CREATE OR REPLACE FUNCTION public.submit_canteen_purchase(p_camp_id uuid, p_camper_name text, p_amount numeric, p_items text DEFAULT ''::text, p_date date DEFAULT NULL::date, p_camper_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_locked_acct jsonb;
    v_name     text;
    v_acct     jsonb;
    v_ar       jsonb;
    v_balance  numeric;
    v_daily    numeric;
    v_spent    numeric;
    v_credit   numeric;
    v_floor    numeric;
    v_lastdate text;
    v_today    text := COALESCE(p_date, (now() AT TIME ZONE 'utc')::date)::text;
    v_utc_today text := (now() AT TIME ZONE 'utc')::date::text;
    v_spendable numeric;
    v_needs_reload_check boolean := false;
    now_ts     timestamptz := now();
BEGIN
    IF auth.uid() IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_authenticated'); END IF;
    IF p_camp_id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'missing_camp'); END IF;
    IF p_amount IS NULL OR p_amount <= 0 OR p_amount > 1000 THEN RETURN jsonb_build_object('success', false, 'error', 'invalid_amount'); END IF;

    -- Staff of THIS camp, accepted. The register's PIN account is one.
    IF NOT public.camp_staff_member(p_camp_id) THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
    END IF;

    -- The person first; the name only for a camper with no id.
    IF p_camper_id IS NOT NULL THEN
        v_name := public.camp_person_name_for(p_camp_id, p_camper_id);
        IF v_name IS NULL THEN
            RETURN jsonb_build_object('success', false, 'error', 'unknown_camper');
        END IF;
    ELSE
        v_name := NULLIF(btrim(COALESCE(p_camper_name, '')), '');
        IF v_name IS NULL THEN
            RETURN jsonb_build_object('success', false, 'error', 'missing_camper');
        END IF;
    END IF;

    -- From here, 219's body with v_name for p_camper_name.
    v_locked_acct := public.canteen_account_lock(p_camp_id, v_name);

    v_acct    := COALESCE(v_locked_acct, '{"balance":0,"dailyLimit":10,"spentToday":0}'::jsonb);
    v_balance := COALESCE((v_acct->>'balance')::numeric, 0);
    v_daily   := COALESCE((v_acct->>'dailyLimit')::numeric, 10);
    v_spent   := COALESCE((v_acct->>'spentToday')::numeric, 0);
    v_credit  := COALESCE((v_acct->>'creditLimit')::numeric, 0);
    v_floor   := COALESCE((v_acct->>'balanceFloor')::numeric, 0);
    v_lastdate := v_acct->>'lastSpendDate';

    IF v_lastdate IS DISTINCT FROM v_today THEN v_spent := 0; END IF;

    IF v_daily > 0 AND (v_spent + p_amount) > v_daily THEN
        RETURN jsonb_build_object('success', false, 'error', 'daily_limit_exceeded',
            'dailyLimit', v_daily, 'spentToday', v_spent, 'remaining', GREATEST(v_daily - v_spent, 0));
    END IF;

    v_spendable := v_balance - v_floor + v_credit;
    IF p_amount > v_spendable THEN
        RETURN jsonb_build_object('success', false, 'error', 'insufficient_balance',
            'spendable', v_spendable, 'balance', v_balance);
    END IF;

    v_balance := round(v_balance - p_amount, 2);
    v_spent   := round(v_spent + p_amount, 2);
    v_acct := v_acct
        || jsonb_build_object('balance', v_balance, 'spentToday', v_spent, 'lastSpendDate', v_today);
    PERFORM public.canteen_account_save(p_camp_id, v_name, v_acct);

    PERFORM public.canteen_post(p_camp_id, v_name,
        jsonb_build_object(
            'time',   to_char(now_ts, 'HH12:MI AM'),
            'camper', v_name,
            'items',  COALESCE(p_items, ''),
            'amount', p_amount,
            'type',   'debit',
            'date',   v_today
        ));

    v_ar := v_acct->'autoReload';
    IF v_ar IS NOT NULL
       AND (v_ar->>'enabled')::boolean IS TRUE
       AND (v_ar->>'cardOnFile')::boolean IS TRUE
       AND (v_ar->>'stripeCustomerId' IS NOT NULL OR v_ar->>'byopCustomerRef' IS NOT NULL)
       AND (v_ar->>'thresholdEnabled')::boolean IS TRUE
       AND (v_ar->>'thresholdAmount') IS NOT NULL
       AND v_balance < (v_ar->>'thresholdAmount')::numeric
       AND (v_ar->>'lastChargedDate') IS DISTINCT FROM v_utc_today
    THEN
        v_needs_reload_check := true;
    END IF;

    RETURN jsonb_build_object('success', true, 'balance', v_balance, 'spentToday', v_spent,
        'camper', v_name, 'needsReloadCheck', v_needs_reload_check);
END;
$function$

CREATE OR REPLACE FUNCTION public.submit_link_tip(p_recipient_name text, p_recipient_role text DEFAULT ''::text, p_amount numeric DEFAULT 0, p_camper_name text DEFAULT NULL::text, p_camp_id text DEFAULT NULL::text, p_camper_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    caller uuid := auth.uid();
    inv    link_parent_invites;
    new_id uuid;
    v_camp uuid;
    v_id   bigint := p_camper_id;
    v_name text;
BEGIN
    IF caller IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
    END IF;
    IF p_recipient_name IS NULL OR btrim(p_recipient_name) = '' THEN
        RETURN jsonb_build_object('success', false, 'error', 'missing_recipient');
    END IF;
    IF p_amount IS NULL OR p_amount < 1 OR p_amount > 500 THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_amount');
    END IF;

    IF COALESCE(btrim(p_camp_id), '') <> '' THEN
        BEGIN
            v_camp := p_camp_id::uuid;
        EXCEPTION WHEN invalid_text_representation THEN
            RETURN jsonb_build_object('success', false, 'error', 'bad_camp');
        END;
    END IF;

    -- A tip may name no camper at all — thanking a counsellor is not about one
    -- child. In that case any active invite will do, as before.
    IF v_id IS NOT NULL OR COALESCE(btrim(p_camper_name), '') <> '' THEN
        inv := public._parent_invite_for(v_camp, v_id, p_camper_name);
        IF inv.id IS NULL THEN
            IF EXISTS (SELECT 1 FROM link_parent_invites
                        WHERE user_id = caller AND status = 'active'
                          AND (expires_at IS NULL OR expires_at > now())
                          AND (v_camp IS NULL OR camp_id = v_camp)) THEN
                RETURN jsonb_build_object('success', false, 'error', 'camper_not_on_invite');
            END IF;
            RETURN jsonb_build_object('success', false, 'error', 'no_active_invite');
        END IF;
        IF v_id IS NOT NULL THEN
            v_name := public.camp_person_name_for(inv.camp_id, v_id);
            IF v_name IS NULL THEN
                RETURN jsonb_build_object('success', false, 'error', 'unknown_camper');
            END IF;
        ELSE
            v_name := p_camper_name;
            v_id   := public.camp_person_by_name(inv.camp_id, v_name);
        END IF;
    ELSE
        SELECT * INTO inv FROM link_parent_invites
         WHERE user_id = caller AND status = 'active'
           AND (expires_at IS NULL OR expires_at > now())
           AND (v_camp IS NULL OR camp_id = v_camp)
         ORDER BY created_at DESC LIMIT 1;
        IF inv.id IS NULL THEN
            RETURN jsonb_build_object('success', false, 'error', 'no_active_invite');
        END IF;
    END IF;

    INSERT INTO link_tips (
        camp_id, invite_id, user_id, camper_name, person_id,
        parent_name, parent_email, recipient_name, recipient_role, amount
    ) VALUES (
        inv.camp_id, inv.id, caller, v_name, v_id,
        inv.parent_name, inv.parent_email,
        btrim(p_recipient_name), coalesce(p_recipient_role, ''), round(p_amount, 2)
    )
    RETURNING id INTO new_id;

    -- Credit the recipient's account in the SAME camp as the resolved invite.
    -- Staff are still keyed by name here: camp_people holds them, but nothing
    -- reads staff ids yet and moving the tip ledger is its own piece of work.
    INSERT INTO link_staff_accounts (camp_id, staff_name, role, balance, total_earned)
    VALUES (inv.camp_id, btrim(p_recipient_name), coalesce(p_recipient_role, ''),
            round(p_amount, 2), round(p_amount, 2))
    ON CONFLICT (camp_id, lower(staff_name)) DO UPDATE
       SET balance      = link_staff_accounts.balance      + EXCLUDED.balance,
           total_earned = link_staff_accounts.total_earned + EXCLUDED.total_earned,
           role         = CASE WHEN link_staff_accounts.role = ''
                               THEN EXCLUDED.role ELSE link_staff_accounts.role END,
           updated_at   = now();

    RETURN jsonb_build_object('success', true, 'id', new_id, 'camper_id', v_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.submit_public_application(p_camp_id uuid, p_kind text, p_entry_id text, p_entry jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_doc      jsonb;
    v_existing jsonb;
    v_status   text;
    v_session  text;
    v_cap      integer;
    v_taken    integer;
    v_entry    jsonb := p_entry;
    v_waited   boolean := false;
BEGIN
    IF p_camp_id IS NULL OR p_entry_id IS NULL OR p_entry IS NULL OR jsonb_typeof(p_entry) <> 'object' THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_payload');
    END IF;
    IF p_kind NOT IN ('enrollments', 'staffApplications') THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_kind');
    END IF;
    IF NOT EXISTS (SELECT 1 FROM camps WHERE id = p_camp_id) THEN
        RETURN jsonb_build_object('success', false, 'error', 'camp_not_found');
    END IF;
    -- 184: the id must be unguessable, because it is the only thing standing
    -- between an anonymous caller and somebody else's record.
    IF length(p_entry_id) < 32 THEN
        RETURN jsonb_build_object('success', false, 'error', 'weak_entry_id');
    END IF;
    -- 083's abuse guard on a genuinely public, unauthenticated endpoint.
    IF pg_column_size(p_entry) > 8388608 THEN
        RETURN jsonb_build_object('success', false, 'error', 'submission_too_large');
    END IF;

    v_session := NULLIF(btrim(COALESCE(p_entry ->> 'session', '')), '');

    -- THE LOCK, NARROWED. 190 held FOR UPDATE on the camp's whole campistryMe
    -- row; this holds an advisory lock over (camp, session) instead. Two
    -- families racing for the last place in 1st Half still serialise — which is
    -- the whole point — while a family registering for 2nd Half, and every
    -- payment webhook writing the blob, no longer queue behind them.
    --
    -- Taken before anything is counted, released at commit. Only registrations
    -- need it: a staff application is not a place.
    IF p_kind = 'enrollments' AND v_session IS NOT NULL THEN
        PERFORM pg_advisory_xact_lock(
            hashtext(p_camp_id::text || '|' || v_session));
    END IF;

    -- The blob is READ, never written here. It is needed for two things: the
    -- session's capacity (the office sets it on the dashboard) and which entry
    -- ids the office has already absorbed.
    SELECT value INTO v_doc
      FROM camp_state_kv
     WHERE camp_id = p_camp_id AND key = 'campistryMe';

    -- 184: a public submission may create, or re-send, an entry that is still
    -- 'applied'. The moment the office has acted on it the public endpoint is
    -- shut out, or anyone who guessed an id could rewrite an accepted camper's
    -- record from an anonymous page.
    --
    -- Checked in BOTH homes: the table for anything submitted since this
    -- migration, the blob for everything before it and for anything the office
    -- has since absorbed and acted on. The blob wins when both have it, because
    -- the office's decision is the newer fact.
    SELECT to_jsonb(a) INTO v_existing
      FROM public.camp_applications a
     WHERE a.camp_id = p_camp_id AND a.kind = p_kind AND a.entry_id = p_entry_id;
    v_status := v_existing ->> 'status';

    IF v_doc IS NOT NULL AND jsonb_typeof(v_doc -> p_kind -> p_entry_id) = 'object' THEN
        v_status := COALESCE(v_doc -> p_kind -> p_entry_id ->> 'status', '');
    END IF;

    IF v_status IS NOT NULL AND v_status NOT IN ('applied', 'waitlisted') THEN
        RETURN jsonb_build_object('success', false, 'error', 'already_processed',
                                  'status', v_status);
    END IF;

    -- CAPACITY. Registrations only. An entry that already exists is being
    -- re-sent, so it is already counted and must not be pushed onto the
    -- waitlist by its own retry.
    IF p_kind = 'enrollments' AND v_session IS NOT NULL AND v_status IS NULL THEN
        SELECT greatest(0, coalesce(NULLIF(s ->> 'capacity', '')::numeric, 0)::integer)
          INTO v_cap
          FROM jsonb_array_elements(coalesce(v_doc -> 'sessions', '[]'::jsonb)) AS s
         WHERE s ->> 'name' = v_session
         LIMIT 1;

        -- A capacity of 0 or absent is UNLIMITED, the same as an empty box on
        -- the dashboard's own session form.
        IF COALESCE(v_cap, 0) > 0 THEN
            v_taken := public._session_taken_all(p_camp_id, coalesce(v_doc, '{}'::jsonb), v_session);
            IF v_taken >= v_cap THEN
                -- Full. Keep everything the family typed and queue them, rather
                -- than refusing and losing twenty minutes of their evening.
                v_entry := v_entry
                    || jsonb_build_object('status', 'waitlisted')
                    || jsonb_build_object('waitlistedAt', to_char(now(), 'YYYY-MM-DD"T"HH24:MI:SSOF'))
                    -- Zeroed on the entry as well as in
                    -- _registration_deposit_owed: a family must not be asked to
                    -- pay to hold a place that does not exist.
                    || jsonb_build_object('depositRequired', 0);
                v_waited := true;
            END IF;
        END IF;
    END IF;

    -- ONE ROW. No lock on the camp, no rewrite of anything shared.
    INSERT INTO public.camp_applications
        (camp_id, kind, entry_id, payload, session, status, submitted_at, updated_at)
    VALUES (p_camp_id, p_kind, p_entry_id, v_entry, v_session,
            COALESCE(v_entry ->> 'status', 'applied'), now(), now())
    ON CONFLICT (camp_id, kind, entry_id) DO UPDATE
       SET payload    = EXCLUDED.payload,
           session    = EXCLUDED.session,
           status     = EXCLUDED.status,
           updated_at = now()
     -- A retry may re-send; anything the office has acted on was refused above,
     -- and this repeats that guard at the row level so a race cannot slip past.
     WHERE public.camp_applications.status IN ('applied', 'waitlisted');

    RETURN jsonb_build_object('success', true, 'id', p_entry_id,
                              'waitlisted', v_waited,
                              'status', COALESCE(v_entry ->> 'status', 'applied'));
END;
$function$

CREATE OR REPLACE FUNCTION public.submit_shop_order(p_camper_name text, p_lines jsonb, p_pay_method text DEFAULT 'bill'::text, p_notes text DEFAULT NULL::text, p_camp_id text DEFAULT NULL::text, p_camper_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_locked_acct jsonb;
    caller     uuid := auth.uid();
    inv        link_parent_invites;
    v_shop     jsonb;
    v_snacks   jsonb;
    v_line     jsonb;
    v_product  jsonb;
    v_variant  text;
    v_qty      int;
    v_unit     numeric;
    v_delta    numeric;
    v_stock    int;
    v_backorder boolean;
    v_lines    jsonb := '[]'::jsonb;
    v_total    numeric := 0;
    v_count    int := 0;
    v_balance  numeric;
    v_order_id text;
    v_bunk     text;
    v_id       bigint := p_camper_id;
    v_name     text;
    v_camp     uuid;
    now_ts     timestamptz := now();
BEGIN
    IF caller IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
    END IF;
    IF COALESCE(btrim(p_camper_name), '') = '' AND v_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'missing_camper');
    END IF;
    IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array' OR jsonb_array_length(p_lines) = 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'empty_order');
    END IF;
    IF jsonb_array_length(p_lines) > 40 THEN
        RETURN jsonb_build_object('success', false, 'error', 'too_many_lines');
    END IF;
    IF p_pay_method IS NULL OR p_pay_method NOT IN ('bill', 'canteen') THEN
        RETURN jsonb_build_object('success', false, 'error', 'invalid_pay_method');
    END IF;

    -- 224's gate, not a fourth copy of the name-containment check. The invite
    -- that COVERS this child, preferring one that names them over the camp-wide
    -- wildcard, rather than whichever the parent created most recently.
    IF COALESCE(btrim(p_camp_id), '') <> '' THEN
        BEGIN
            v_camp := p_camp_id::uuid;
        EXCEPTION WHEN invalid_text_representation THEN
            -- A camp id that is not a camp must refuse, not widen the search to
            -- every camp this parent belongs to.
            RETURN jsonb_build_object('success', false, 'error', 'bad_camp');
        END;
    END IF;

    inv := public._parent_invite_for(v_camp, v_id, p_camper_name);
    IF inv.id IS NULL THEN
        -- Told apart, so a parent is not sent to the camp about a missing invite
        -- they do have.
        IF EXISTS (SELECT 1 FROM link_parent_invites
                    WHERE user_id = caller AND status = 'active'
                      AND (expires_at IS NULL OR expires_at > now())
                      AND (v_camp IS NULL OR camp_id = v_camp)) THEN
            RETURN jsonb_build_object('success', false, 'error', 'camper_not_on_invite');
        END IF;
        RETURN jsonb_build_object('success', false, 'error', 'no_active_invite');
    END IF;

    -- The label comes from the roster when an id was given, never from the name
    -- beside it.
    IF v_id IS NOT NULL THEN
        v_name := public.camp_person_name_for(inv.camp_id, v_id);
        IF v_name IS NULL THEN
            RETURN jsonb_build_object('success', false, 'error', 'unknown_camper');
        END IF;
    ELSE
        v_name := p_camper_name;
        v_id   := public.camp_person_by_name(inv.camp_id, v_name);
    END IF;

    -- Guarantee a row exists, then lock it. Lock order is always
    -- campistryShop -> campistrySnacks (see security note 5).
    INSERT INTO camp_state_kv (camp_id, key, value, updated_at)
    VALUES (inv.camp_id, 'campistryShop', '{"products":[],"orders":[],"settings":{}}'::jsonb, now_ts)
    ON CONFLICT (camp_id, key) DO NOTHING;

    SELECT value INTO v_shop
    FROM camp_state_kv
    WHERE camp_id = inv.camp_id AND key = 'campistryShop'
    FOR UPDATE;

    IF v_shop IS NULL THEN v_shop := '{"products":[],"orders":[],"settings":{}}'::jsonb; END IF;
    v_backorder := COALESCE((v_shop->'settings'->>'parentAllowBackorder')::boolean, false);

    -- ── price and validate every line from the STORED catalogue ──
    FOR v_line IN SELECT * FROM jsonb_array_elements(p_lines)
    LOOP
        v_qty := GREATEST(0, COALESCE((v_line->>'qty')::int, 0));
        CONTINUE WHEN v_qty = 0;
        IF v_qty > 50 THEN
            RETURN jsonb_build_object('success', false, 'error', 'qty_too_large');
        END IF;

        v_product := NULL;   -- explicit: never inherit the previous iteration's row
        SELECT p INTO v_product
        FROM jsonb_array_elements(COALESCE(v_shop->'products', '[]'::jsonb)) AS p
        WHERE p->>'id' = v_line->>'productId'
          AND COALESCE((p->>'active')::boolean, true) IS TRUE
        LIMIT 1;

        IF v_product IS NULL THEN
            RETURN jsonb_build_object('success', false, 'error', 'product_unavailable',
                                      'productId', v_line->>'productId');
        END IF;

        -- Variant id mirrors ShopCore.variantId(): slug(sku|id):slug(size):slug(color)
        -- Each segment is trimmed SEPARATELY, exactly as slug() does in JS.
        -- Trimming the joined string instead would leave 'tee-:am:navy' for a
        -- sku like "TEE!", which matches nothing in the stock map — the stock
        -- check would then silently pass on every order.
        v_variant :=
            btrim(regexp_replace(lower(COALESCE(NULLIF(v_product->>'sku',''), v_product->>'id')), '[^a-z0-9]+', '-', 'g'), '-')
            || ':' ||
            btrim(regexp_replace(lower(COALESCE(NULLIF(v_line->>'size',''), 'onesize')), '[^a-z0-9]+', '-', 'g'), '-')
            || ':' ||
            btrim(regexp_replace(lower(COALESCE(NULLIF(v_line->>'color',''), 'default')), '[^a-z0-9]+', '-', 'g'), '-');

        v_delta := COALESCE((v_product->'priceDeltas'->>(v_line->>'size'))::numeric, 0);
        v_unit  := round(COALESCE((v_product->>'price')::numeric, 0) + v_delta, 2);

        IF NOT v_backorder THEN
            v_stock := COALESCE((v_product->'stock'->>v_variant)::int, 0);
            IF v_qty > v_stock THEN
                RETURN jsonb_build_object('success', false, 'error', 'out_of_stock',
                    'product', v_product->>'name', 'size', v_line->>'size',
                    'available', v_stock, 'wanted', v_qty);
            END IF;
        END IF;

        v_total := v_total + (v_unit * v_qty);
        v_count := v_count + v_qty;
        v_lines := v_lines || jsonb_build_array(jsonb_build_object(
            'productId', (v_product->>'id')::int,
            'name',      v_product->>'name',
            'size',      COALESCE(v_line->>'size', ''),
            'color',     COALESCE(v_line->>'color', ''),
            'qty',       v_qty,
            'unitPrice', v_unit
        ));
    END LOOP;

    IF jsonb_array_length(v_lines) = 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'empty_order');
    END IF;
    v_total := round(v_total, 2);

    -- ── canteen payment: draw the total from the camper's balance ──
    IF p_pay_method = 'canteen' THEN

    -- 219: one camper's row, not the camp's document.
    v_snacks := NULL::jsonb;  -- document no longer read
    v_locked_acct := public.canteen_account_lock(inv.camp_id, v_name);

        v_balance := COALESCE((v_locked_acct->>'balance')::numeric, 0);

        IF v_balance < v_total THEN
            RETURN jsonb_build_object('success', false, 'error', 'insufficient_balance',
                                      'balance', v_balance, 'total', v_total);
        END IF;

        v_balance := round(v_balance - v_total, 2);
    PERFORM public.canteen_account_save(inv.camp_id, v_name,
        COALESCE(v_locked_acct, '{"dailyLimit":10,"spentToday":0}'::jsonb)
                || jsonb_build_object('balance', v_balance));
        -- kind 'shop' so canteen revenue reporting doesn't count it as a
        -- snack sale, matching how cash_out is kept separate.
    PERFORM public.canteen_post(inv.camp_id, v_name,
        jsonb_build_object(
                'time',   to_char(now_ts, 'HH12:MI AM'),
                'camper', v_name,
                'items',  'Camp Shop order',
                'amount', v_total,
                'type',   'debit',
                'kind',   'shop',
                'date',   to_char(now_ts, 'YYYY-MM-DD')
            ));

    END IF;

    -- Bunk, so the office's pick list groups the order without a lookup.
    SELECT value->'camperRoster'->v_name->>'bunk' INTO v_bunk
    FROM camp_state_kv WHERE camp_id = inv.camp_id AND key = 'app1';

    v_order_id := 'ord_p_' || replace(gen_random_uuid()::text, '-', '');

    v_shop := jsonb_set(
        v_shop, '{orders}',
        COALESCE(v_shop->'orders', '[]'::jsonb) || jsonb_build_array(jsonb_build_object(
            'id',          v_order_id,
            'camperName',  v_name,
            'bunk',        COALESCE(v_bunk, ''),
            'lines',       v_lines,
            'status',      'placed',
            'paid',        (p_pay_method = 'canteen'),
            'payMethod',   p_pay_method,
            'camperId',    v_id,
            -- THE FIX. 167 built settle_shop_order around the order carrying a
            -- `settlement` record of what was ACTUALLY taken, so a re-save posts
            -- only the DIFFERENCE. This function predates 167: it took the money
            -- from the canteen and wrote no settlement, so the first time the
            -- office saved a parent's canteen-paid order settle_shop_order read
            -- method 'none' and amount 0, and charged the camper the whole total
            -- a SECOND time.
            'settlement',  CASE WHEN p_pay_method = 'canteen'
                                THEN jsonb_build_object(
                                    'method', 'canteen',
                                    'amount', v_total,
                                    'familyKey', NULL,
                                    'at', to_char(now_ts, 'YYYY-MM-DD"T"HH24:MI:SS"Z"'))
                           END,
            'notes',       COALESCE(p_notes, ''),
            'placedAt',    to_char(now_ts, 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
            'source',      'parent'
        )),
        true
    );

    UPDATE camp_state_kv
    SET value = v_shop, updated_at = now_ts
    WHERE camp_id = inv.camp_id AND key = 'campistryShop';

    RETURN jsonb_build_object(
        'success', true, 'orderId', v_order_id,
        'total', v_total, 'items', v_count,
        'paid', (p_pay_method = 'canteen'),
        'balance', v_balance
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_camp_billing(p_camp_id uuid, p_families_upsert jsonb DEFAULT '{}'::jsonb, p_families_delete jsonb DEFAULT '[]'::jsonb, p_payments_upsert jsonb DEFAULT '[]'::jsonb, p_payments_delete jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    now_ts  timestamptz := now();
    r       record;
    v_famUp integer := 0;
    v_famDel integer := 0;
    v_payUp integer := 0;
    v_payDel integer := 0;
BEGIN
    IF auth.uid() IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
    END IF;
    IF p_camp_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'missing_camp');
    END IF;
    IF NOT public.camp_staff_member(p_camp_id)
       OR COALESCE(public.user_section_level(p_camp_id, 'me.billing'), 'none') <> 'edit' THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
    END IF;

    -- families
    IF jsonb_typeof(p_families_upsert) = 'object' THEN
        FOR r IN SELECT key, value FROM jsonb_each(p_families_upsert)
                  WHERE jsonb_typeof(value) = 'object' LOOP
            PERFORM public.camp_family_save(p_camp_id, r.key, public._merge_family_from_page((SELECT f.payload FROM public.camp_families f WHERE f.camp_id = p_camp_id AND f.family_key = r.key AND f.deleted_at IS NULL), r.value));
            v_famUp := v_famUp + 1;
        END LOOP;
    END IF;
    IF jsonb_typeof(p_families_delete) = 'array' THEN
        UPDATE public.camp_families
           SET deleted_at = now_ts, updated_at = now_ts
         WHERE camp_id = p_camp_id
           AND deleted_at IS NULL
           AND family_key IN (SELECT jsonb_array_elements_text(p_families_delete));
        GET DIAGNOSTICS v_famDel = ROW_COUNT;
    END IF;

    -- payments
    IF jsonb_typeof(p_payments_upsert) = 'array' THEN
        FOR r IN SELECT value FROM jsonb_array_elements(p_payments_upsert) AS t(value)
                  WHERE jsonb_typeof(t.value) = 'object' LOOP
            INSERT INTO public.camp_payments
                (camp_id, payment_id, family_name, family_key, enrollment_id,
                 status, amount, pay_date, payload)
            VALUES (p_camp_id, public.camp_payment_identity(r.value),
                    COALESCE(r.value ->> 'family', ''),
                    COALESCE(r.value ->> 'familyKey', ''),
                    COALESCE(r.value ->> 'enrollmentId', ''),
                    COALESCE(r.value ->> 'status', ''),
                    COALESCE(public._num_or_null(r.value ->> 'amount'), 0),
                    COALESCE(r.value ->> 'date', ''),
                    r.value)
            ON CONFLICT (camp_id, payment_id) DO UPDATE
               SET family_name = EXCLUDED.family_name,
                   family_key = EXCLUDED.family_key,
                   enrollment_id = EXCLUDED.enrollment_id,
                   status = EXCLUDED.status, amount = EXCLUDED.amount,
                   pay_date = EXCLUDED.pay_date, payload = EXCLUDED.payload,
                   deleted_at = NULL, updated_at = now_ts;
            v_payUp := v_payUp + 1;
        END LOOP;
    END IF;
    IF jsonb_typeof(p_payments_delete) = 'array' THEN
        -- Stamped, not destroyed: the office's Undo clears it by upserting the
        -- payment again, and nothing is ever lost to a mis-click.
        UPDATE public.camp_payments
           SET deleted_at = now_ts, updated_at = now_ts
         WHERE camp_id = p_camp_id
           AND deleted_at IS NULL
           AND payment_id IN (SELECT jsonb_array_elements_text(p_payments_delete));
        GET DIAGNOSTICS v_payDel = ROW_COUNT;
    END IF;

    RETURN jsonb_build_object('success', true,
        'familiesUpserted', v_famUp, 'familiesDeleted', v_famDel,
        'paymentsUpserted', v_payUp, 'paymentsDeleted', v_payDel);
END;
$function$

CREATE OR REPLACE FUNCTION public.use_family_card_for_canteen_auto_reload(p_camp_id uuid, p_camper_name text, p_payment_method_id text DEFAULT NULL::text, p_camper_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    caller   uuid := auth.uid();
    inv      link_parent_invites;
    v_id     bigint;
    v_name   text;
    v_famKey text;
    v_fam    jsonb;
    v_pm     jsonb;
    v_picked jsonb := NULL;
    v_acct   jsonb;
    -- Restored with the card selection below: 234 dropped these and wrote a
    -- paymentMethodId the charger does not read.
    v_ar             jsonb;
    v_processorKey   text;
    v_cardLabel      text;
    v_token          text;
    v_stripeCustomerId text;
    now_ts           timestamptz := now();
BEGIN
    IF caller IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
    END IF;

    SELECT * INTO inv
      FROM link_parent_invites
     WHERE user_id = caller AND status = 'active'
       AND (expires_at IS NULL OR expires_at > now())
       AND (p_camp_id IS NULL OR camp_id = p_camp_id)
     ORDER BY created_at DESC
     LIMIT 1;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'no_active_invite');
    END IF;

    -- The shared gate decides whose child this is; this function never asks the
    -- camper question itself.
    v_id := COALESCE(p_camper_id, public.camp_person_by_name(inv.camp_id, p_camper_name));
    IF v_id IS NOT NULL THEN
        IF NOT public._invite_covers_person(inv.id, v_id) THEN
            RETURN jsonb_build_object('success', false, 'error', 'camper_not_on_invite');
        END IF;
    ELSIF NOT public._invite_covers_camper(inv.id, p_camper_name) THEN
        RETURN jsonb_build_object('success', false, 'error', 'camper_not_on_invite');
    END IF;

    v_name := COALESCE(public.camp_person_name_for(inv.camp_id, v_id), p_camper_name);

    -- 233: two of 231's three comparisons, in one place.
    v_famKey := public.camp_family_key_for_person(inv.camp_id, v_id, v_name);

    -- The third. An invite and a family snapshot are produced by the same office
    -- sync from the same roster keys, so they are the same vintage: when
    -- camperIds holds a spelling the roster has since dropped, the invite holds
    -- it too, and 223 stamped that slot with the id. Nothing else can bridge
    -- that, which is why it is still here and why it is last.
    IF v_famKey IS NULL AND v_id IS NOT NULL
       AND jsonb_typeof(inv.camper_names) = 'array' THEN
        SELECT f.family_key INTO v_famKey
          FROM public.camp_families f
         WHERE f.camp_id = inv.camp_id AND f.deleted_at IS NULL
           AND EXISTS (
               SELECT 1
                 FROM jsonb_array_elements_text(f.camper_ids) AS ci
                 CROSS JOIN LATERAL jsonb_array_elements(inv.camper_names)
                            WITH ORDINALITY AS e(value, ord)
                WHERE e.value #>> '{}' = ci
                  AND COALESCE(inv.person_ids -> (e.ord - 1)::int, 'null'::jsonb)
                      = to_jsonb(v_id))
         ORDER BY f.family_key
         LIMIT 1;
    END IF;

    IF v_famKey IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'family_not_found');
    END IF;

    SELECT f.payload INTO v_fam
      FROM public.camp_families f
     WHERE f.camp_id = inv.camp_id AND f.family_key = v_famKey;

    -- ── THE CARD, RESTORED FROM 231 ────────────────────────────────────────
    -- 234 replaced everything from here to the RETURN with a much thinner write:
    --
    --     'paymentMethodId', v_picked->>'id', 'last4', …, 'brand', …, 'source','family'
    --
    -- and a refusal of no_saved_card whenever savedPaymentMethods was absent. Both
    -- halves of that were wrong.
    --
    --   * THE CHARGER DOES NOT READ paymentMethodId. canteen-auto-reload skips a
    --     camper on `if (!ar.stripeCustomerId && !ar.byopCustomerRef) continue`, so
    --     after 234 a parent attached their family card, the call answered success,
    --     and the nightly run found no card on file and moved on. That is the exact
    --     defect 231 was written to fix — "the card was written where no reader
    --     looks" — put back by the file that was only supposed to change how the
    --     FAMILY is found.
    --   * A family whose card is in the LEGACY single-slot fields has no
    --     savedPaymentMethods entry to pick. 138's behaviour, which 231 kept, reads
    --     byopCustomerRef / stripeCustomerId directly; 234 answered no_saved_card.
    --
    -- So this is 231's block verbatim: it picks the named method or the family's
    -- current default, writes the token the charger actually reads, CLEARS the other
    -- processor's stale token (or a camper ends up with two), stamps cardSavedDate,
    -- and resets the failure counters that stopped the last card being retried.
    IF p_payment_method_id IS NOT NULL THEN
        FOR v_pm IN SELECT * FROM jsonb_array_elements(COALESCE(v_fam->'savedPaymentMethods', '[]'::jsonb)) LOOP
            IF v_pm->>'id' = p_payment_method_id THEN v_picked := v_pm; EXIT; END IF;
        END LOOP;
        IF v_picked IS NULL THEN
            RETURN jsonb_build_object('success', false, 'error', 'method_not_found');
        END IF;
        v_processorKey := v_picked->>'processor';
        v_cardLabel := v_picked->>'label';
        v_token := v_picked->>'token';
        v_stripeCustomerId := v_picked->>'stripeCustomerId';
    ELSE
        -- Original migration 138 behavior — the family's current default.
        IF v_fam->>'byopCustomerRef' IS NOT NULL AND v_fam->>'byopCustomerRef' <> '' THEN
            v_processorKey := COALESCE(v_fam->>'byopProcessor', 'cardknox');
            v_token := v_fam->>'byopCustomerRef';
        ELSIF v_fam->>'stripeCustomerId' IS NOT NULL AND v_fam->>'stripeCustomerId' <> ''
              AND COALESCE((v_fam->>'cardOnFile')::boolean, false) THEN
            v_processorKey := 'stripe';
            v_token := v_fam->>'stripePaymentMethodId';
            v_stripeCustomerId := v_fam->>'stripeCustomerId';
        ELSE
            RETURN jsonb_build_object('success', false, 'error', 'no_card_on_file');
        END IF;
        v_cardLabel := v_fam->>'paymentMethodLabel';
    END IF;

    -- THE SECOND DEFECT IN THIS FUNCTION, and the one with teeth. 219 moved the
    -- canteen off the campistrySnacks document onto camp_canteen_accounts rows,
    -- and converted the TWO-argument version of this function. The
    -- three-argument version from 214 — the one that is actually live — was
    -- never converted. It has been reading and writing the document ever since,
    -- and since 219 nothing reads that document: the card was written where no
    -- reader looks, so auto-reload has never found a card on file for anyone who
    -- attached one this way. It also took a camp-wide lock on campistrySnacks,
    -- which is the contention 219 existed to remove.
    v_acct := COALESCE(public.canteen_account_lock(inv.camp_id, v_name),
                       '{"balance":0,"dailyLimit":10,"spentToday":0}'::jsonb);
    IF jsonb_typeof(v_acct) <> 'object' OR v_acct = '{}'::jsonb THEN
        v_acct := '{"balance":0,"dailyLimit":10,"spentToday":0}'::jsonb;
    END IF;
    v_ar   := COALESCE(v_acct->'autoReload', '{}'::jsonb);

    IF v_processorKey = 'cardknox' THEN
        v_ar := (v_ar - 'stripeCustomerId') - 'stripePaymentMethodId';
        v_ar := v_ar || jsonb_build_object(
            'byopProcessor', v_processorKey,
            'byopCustomerRef', v_token,
            'cardOnFile', true,
            'paymentMethodType', 'card'
        );
    ELSE
        v_ar := (v_ar - 'byopCustomerRef') - 'byopProcessor';
        v_ar := v_ar || jsonb_build_object(
            'stripeCustomerId', v_stripeCustomerId,
            'stripePaymentMethodId', v_token,
            'cardOnFile', true,
            'paymentMethodType', 'card'
        );
    END IF;
    IF v_cardLabel IS NOT NULL THEN
        v_ar := jsonb_set(v_ar, '{paymentMethodLabel}', to_jsonb(v_cardLabel), true);
    END IF;
    v_ar := jsonb_set(v_ar, '{cardSavedDate}', to_jsonb(now_ts), true);
    v_ar := (v_ar - 'lastFailureDate') - 'lastFailureReason';
    v_ar := jsonb_set(v_ar, '{consecutiveFailures}', '0'::jsonb, true);

    v_acct   := jsonb_set(v_acct, '{autoReload}', v_ar, true);
    PERFORM public.canteen_account_save(inv.camp_id, v_name, v_acct);

    RETURN jsonb_build_object(
        'success', true,
        'processorKey', v_processorKey,
        'cardLabel', v_cardLabel,
        'autoReload', v_ar
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.verify_camp_billing_projection(p_camp_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_claims  text := NULLIF(current_setting('request.jwt.claims', true), '');
    v_me      jsonb;
    v_stamp   timestamptz;
    v_proj    timestamptz;
    v_bEnr    integer; v_pEnr integer;
    v_bFam    integer; v_pFam integer;
    v_bPay    integer; v_pPay integer;
    v_cfgOk   boolean;
BEGIN
    IF v_claims IS NOT NULL
       AND COALESCE(v_claims::jsonb ->> 'role', '') <> 'service_role'
       AND NOT public.camp_reader(p_camp_id) THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
    END IF;

    SELECT value, updated_at INTO v_me, v_stamp FROM camp_state_kv
     WHERE camp_id = p_camp_id AND key = 'campistryMe';
    SELECT blob_updated_at INTO v_proj FROM public.camp_billing_config WHERE camp_id = p_camp_id;

    SELECT count(*)::integer INTO v_bEnr FROM jsonb_each(
        CASE WHEN jsonb_typeof(v_me -> 'enrollments') = 'object' THEN v_me -> 'enrollments' ELSE '{}'::jsonb END) e
      WHERE jsonb_typeof(e.value) = 'object';
    SELECT count(*)::integer INTO v_bFam FROM jsonb_each(
        CASE WHEN jsonb_typeof(v_me -> 'families') = 'object' THEN v_me -> 'families' ELSE '{}'::jsonb END) f
      WHERE jsonb_typeof(f.value) = 'object';
    SELECT count(*)::integer INTO v_bPay FROM jsonb_array_elements(
        CASE WHEN jsonb_typeof(v_me -> 'finance' -> 'payments') = 'array'
             THEN v_me -> 'finance' -> 'payments' ELSE '[]'::jsonb END) p
      WHERE jsonb_typeof(p.value) = 'object';

    SELECT count(*)::integer INTO v_pEnr FROM public.camp_billing_enrollments WHERE camp_id = p_camp_id;
    SELECT count(*)::integer INTO v_pFam FROM public.camp_billing_families    WHERE camp_id = p_camp_id;
    SELECT count(*)::integer INTO v_pPay FROM public.camp_billing_payments    WHERE camp_id = p_camp_id;

    SELECT COALESCE(sessions, '[]'::jsonb) IS NOT DISTINCT FROM
           COALESCE(CASE WHEN jsonb_typeof(v_me -> 'sessions') = 'array'
                         THEN v_me -> 'sessions' ELSE '[]'::jsonb END, '[]'::jsonb)
      INTO v_cfgOk FROM public.camp_billing_config WHERE camp_id = p_camp_id;

    RETURN jsonb_build_object(
        'success', true,
        'onFastPath', (v_stamp IS NOT NULL AND v_proj IS NOT NULL AND v_proj = v_stamp),
        'inSync', (v_bEnr = COALESCE(v_pEnr, -1) AND v_bFam = COALESCE(v_pFam, -1)
                   AND v_bPay = COALESCE(v_pPay, -1) AND COALESCE(v_cfgOk, false)),
        'enrollments', jsonb_build_object('blob', v_bEnr, 'projected', v_pEnr),
        'families',    jsonb_build_object('blob', v_bFam, 'projected', v_pFam),
        'payments',    jsonb_build_object('blob', v_bPay, 'projected', v_pPay),
        'sessionsMatch', COALESCE(v_cfgOk, false),
        'note', 'onFastPath false is SAFE — the balance falls back to reading the blob, which is its pre-205 behaviour',
        'repair', 're-paste migrations/205_parent_balance_off_the_blob.sql, or save Camp Dates once to re-fire the trigger');
END;
$function$

CREATE OR REPLACE FUNCTION public.verify_canteen_archive(p_camp_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_value    jsonb;
    v_total    integer := 0;
    v_missing  integer := 0;
    v_archived integer;
    v_claims   text := NULLIF(current_setting('request.jwt.claims', true), '');
    t          jsonb;
BEGIN
    IF v_claims IS NOT NULL
       AND COALESCE(v_claims::jsonb ->> 'role', '') <> 'service_role'
       AND NOT public.camp_reader(p_camp_id) THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
    END IF;

    SELECT value INTO v_value FROM camp_state_kv
     WHERE camp_id = p_camp_id AND key = 'campistrySnacks';

    FOR t IN SELECT * FROM jsonb_array_elements(
                 CASE WHEN jsonb_typeof(v_value -> 'transactions') = 'array'
                      THEN v_value -> 'transactions' ELSE '[]'::jsonb END) LOOP
        IF jsonb_typeof(t) <> 'object' THEN CONTINUE; END IF;
        v_total := v_total + 1;
        IF NOT EXISTS (SELECT 1 FROM public.canteen_transactions ct
                        WHERE ct.camp_id = p_camp_id
                          AND ct.sig = public.canteen_tx_sig(t)) THEN
            v_missing := v_missing + 1;
        END IF;
    END LOOP;

    SELECT count(*)::integer INTO v_archived
      FROM public.canteen_transactions WHERE camp_id = p_camp_id;

    RETURN jsonb_build_object(
        'success', true,
        'inSync', v_missing = 0,
        'blobTransactions', v_total,
        'missingFromArchive', v_missing,
        'archivedTotal', v_archived,
        'note', 'archivedTotal may exceed blobTransactions — the archive keeps what the blob has lost, which is the point',
        'repair', 're-paste migrations/203_canteen_archive.sql — its backfill converges');
END;
$function$

CREATE OR REPLACE FUNCTION public.verify_payments_read_swap(p_camp_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_claims  text := NULLIF(current_setting('request.jwt.claims', true), '');
    v_oldAll  jsonb;
    v_newAll  jsonb;
    v_oldSum  numeric := 0;
    v_newSum  numeric := 0;
    v_projectionPresent boolean;
BEGIN
    IF p_camp_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'missing_camp');
    END IF;
    IF v_claims IS NOT NULL
       AND COALESCE(v_claims::jsonb ->> 'role', '') <> 'service_role'
       AND NOT public.camp_reader(p_camp_id) THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
    END IF;

    v_projectionPresent := to_regclass('public.camp_billing_payments') IS NOT NULL;

    -- The whole camp, from both homes, in each home's own order.
    IF v_projectionPresent THEN
        EXECUTE 'SELECT COALESCE(jsonb_agg(payload ORDER BY seq), ''[]''::jsonb)
                   FROM public.camp_billing_payments WHERE camp_id = $1'
           INTO v_oldAll USING p_camp_id;
    ELSE
        v_oldAll := NULL;
    END IF;

    SELECT COALESCE(jsonb_agg(payload ORDER BY ordinal), '[]'::jsonb)
      INTO v_newAll
      FROM public.camp_payments WHERE camp_id = p_camp_id;

    SELECT COALESCE(sum(COALESCE(public._num_or_null(e ->> 'amount'), 0)), 0) INTO v_newSum
      FROM jsonb_array_elements(COALESCE(v_newAll, '[]'::jsonb)) AS e
     WHERE COALESCE(e ->> 'status', '') NOT IN ('pending', 'failed');

    IF v_oldAll IS NOT NULL THEN
        SELECT COALESCE(sum(COALESCE(public._num_or_null(e ->> 'amount'), 0)), 0) INTO v_oldSum
          FROM jsonb_array_elements(v_oldAll) AS e
         WHERE COALESCE(e ->> 'status', '') NOT IN ('pending', 'failed');
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        -- When 205's projection is gone there is nothing to compare against, and
        -- that is not a failure — it is what phase 2b's cleanup leaves behind.
        'comparable', v_oldAll IS NOT NULL,
        'sameOrderAndContent', CASE WHEN v_oldAll IS NULL THEN NULL
                                    ELSE v_oldAll = v_newAll END,
        'collectedOld', CASE WHEN v_oldAll IS NULL THEN NULL ELSE v_oldSum END,
        'collectedNew', v_newSum,
        'countOld', CASE WHEN v_oldAll IS NULL THEN NULL
                         ELSE jsonb_array_length(v_oldAll) END,
        'countNew', jsonb_array_length(COALESCE(v_newAll, '[]'::jsonb)),
        'note', 'sameOrderAndContent true means the office and the parent see '
             || 'exactly what they saw before the swap. If it is false, compare '
             || 'collectedOld against collectedNew: equal money with a different '
             || 'order is a display question, unequal money is not.');
END;
$function$
